// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Çokgenler, özel dörtgenler ve çemberde açı-kiriş-teğet-kuvvet özellikleri (yamuk, eşkenar dörtgen, deltoid, kirişler ve teğetler dörtgeni) (orta).
const ozMathematics16Orta = <(String, String, List<String>, String)>[
  ('Köşegenlerinin toplam adedi, kenar sayısının tam 4 katına eşit olan dışbükey çokgenin iç açılarının ölçüleri toplamı kaç dik açıya karşılık gelir?', '18 dik açıya karşılık gelir', ['14 dik açıya karşılık gelir', '20 dik açıya karşılık gelir', '22 dik açıya karşılık gelir'], 'n(n-3)/2 = 4n eşitliğinden n - 3 = 8 ve n = 11 bulunur. İç açılar toplamı (11 - 2)·180° = 9·2·90° = 18 dik açıdır.'),
  ('Düzgün sekizgen ve kare biçimindeki mermer plakalar birlikte kullanılarak yarı düzgün (Arşimet tipi) bir zemin kaplaması yapılmaktadır. Kaplamanın herhangi bir birleşim köşesinde bir araya gelen çokgenlerin dağılımı nasıldır?', 'İki düzgün sekizgen ve bir kare', ['Bir düzgün sekizgen ve üç kare', 'Üç düzgün sekizgen ve bir kare', 'İki düzgün sekizgen ve iki kare'], 'Düzgün sekizgenin bir iç açısı 135°, karenin iç açısı 90°\'dir. Bir köşede 135° + 135° + 90° = 360° olduğundan iki sekizgen ve bir kare buluşur.'),
  ('Bir konveks çokgenin üç iç açısının ölçüleri sırasıyla 115°, 125° ve 140° olarak verilmiştir. Geriye kalan tüm iç açıların her biri 160° olduğuna göre bu çokgenin toplam kenar sayısı kaçtır?', '13 kenarı bulunmaktadır', ['11 kenarı bulunmaktadır', '15 kenarı bulunmaktadır', '16 kenarı bulunmaktadır'], 'Verilen üç köşenin dış açıları 65°, 55° ve 40° olup toplamları 160° eder. Kalan (n-3) dış açının her biri 20° olduğundan 160 + 20(n-3) = 360 eşitliğinden n - 3 = 10 ve n = 13 bulunur.'),
  ('Düzlemde tek bir köşesinden çizilen tüm köşegenler yardımıyla birbirine komşu 9 adet üçgensel bölgeye ayrılabilen dışbükey çokgenin toplam köşegen sayısı kaçtır?', '44 köşegeni vardır', ['35 köşegeni vardır', '54 köşegeni vardır', '27 köşegeni vardır'], 'Bir köşeden çizilen köşegenler çokgeni (n - 2) üçgene ayırır; n - 2 = 9 ise n = 11 olur. Toplam köşegen sayısı 11·(11 - 3)/2 = 44 olarak hesaplanır.'),
  ('Kenar sayısı çift olan bir düzgün çokgenin simetri eksenlerinin yapısı incelendiğinde tek kenarlı düzgün çokgenlerden hangi temel farkla ayrıldığı görülür?', 'Eksenlerin yarısı karşılıklı köşelerden, diğer yarısı karşılıklı kenar ortalarından geçer', ['Tüm simetri eksenleri bir köşeden girip karşıdaki kenarın orta noktasından çıkar', 'Simetri ekseni sayısı kenar sayısının iki katına ulaşarak çember simetrisi oluşturur', 'Yalnızca köşegenler simetri ekseni oluşturur, kenar ortalarını birleştiren doğrular eksen değildir'], 'Çift kenarlı (2k) düzgün çokgenlerde k tane simetri ekseni karşılıklı köşeleri, kalan k tane eksen ise karşılıklı kenarların orta noktalarını birleştirir.'),
  ('Bir iç açısının ölçüsü, bir dış açısının ölçüsünün 7 katından 20 derece fazla olan düzgün çokgenin çevresi 90 birim ise bir kenarı kaç birimdir?', '5 birim uzunluğundadır', ['6 birim uzunluğundadır', '9 birim uzunluğundadır', '10 birim uzunluğundadır'], 'Dış açıya x denirse iç açı 7x + 20 olur. 8x + 20 = 180 eşitliğinden x = 20° ve kenar sayısı 360/20 = 18 bulunur; bir kenar 90/18 = 5 birimdir.'),
  ('ABCDEF düzgün altıgeninin içine, bir kenarı altıgenin [AB] kenarı ile çakışacak biçimde ABKLM düzgün beşgeni çiziliyor. Altıgenin F köşesi, A köşesi ve beşgenin M köşesinin oluşturduğu FAM açısı kaç derecedir?', '12 derecelik dar açıdır', ['15 derecelik dar açıdır', '18 derecelik dar açıdır', '24 derecelik dar açıdır'], 'Altıgenin FAB iç açısı 120°, beşgenin MAB iç açısı 108°\'dir. İki çokgen aynı [AB] tabanı üzerinde iç içe bulunduğundan m(FAM) = 120° - 108° = 12° olur.'),
  ('ABCDE düzgün beşgeninin içinde seçilen bir P noktası ile [CD] kenarı kullanılarak eşkenar bir PCD üçgeni oluşturuluyor. Buna göre AEP açısının ölçüsü kaç derecedir?', '42 derece ölçülür', ['36 derece ölçülür', '48 derece ölçülür', '54 derece ölçülür'], 'Düzgün beşgende |ED| = |CD| ve eşkenar üçgende |PD| = |CD| olduğundan |ED| = |PD| ikizkenar üçgeni doğar. m(EDC)=108° ve m(PDC)=60° ise m(EDP)=48°; buradan m(DEP)=(180°-48°)/2=66° bulunur. m(AED)=108° olduğundan m(AEP)=108°-66°=42° elde edilir.'),
  ('Düzgün onikigen biçimindeki bir duvar saatinin çevrel çember yarıçapı 10 santimetre ise bu saatin ön yüzünün alanı kaç santimetrekaredir?', '300 santimetrekare', ['240 santimetrekare', '150√3 santimetrekare', '200√2 santimetrekare'], 'Düzgün onikigen merkezden çizilen yarıçaplarla tepe açısı 360°/12 = 30° olan 12 eş ikizkenar üçgene ayrılır. Toplam alan = 12 · (1/2 · 10 · 10 · sin30°) = 12 · 25 = 300 cm² olur.'),
  ('Herhangi bir dışbükey çokgende iç açılardan en çok kaç tanesi dar açı (90 dereceden küçük) özelliğine sahip olabilir?', 'En çok 3 tanesi dar açı olabilir', ['En çok 2 tanesi dar açı olabilir', 'En çok 4 tanesi dar açı olabilir', 'Kenar sayısının yarısı kadarı olabilir'], 'Dar iç açının dış açısı 90°\'den büyüktür. Eğer 4 tane dar iç açı olsaydı bu dört köşenin dış açıları toplamı 360°\'yi aşardı; dış açılar toplamı 360° olduğundan en fazla 3 dar iç açı bulunabilir.'),
  ('Bir düzgün beşgende bir köşegen uzunluğunun bir kenar uzunluğuna oranı matematik tarihinde hangi özel sabit sayıya karşılık gelir?', 'Altın orana ((1 + √5) / 2)', ['Gümüş orana', 'Karekök üçe', 'Euler sayısının yarısına'], 'Düzgün beşgende tepe açısı 36°, taban açıları 72° olan altın üçgenlerde benzerlik yazıldığında köşegen/kenar oranı d/a = (1 + √5)/2 yani altın oran (φ) bulunur.'),
  ('ABCDEF düzgün altıgeninde E ve F köşeleri, [AB] kenarının orta noktası olan M ile birleştirilerek EFM üçgeni oluşturuluyor. Bu üçgenin alanının tüm altıgenin alanına oranı kaçtır?', '1/3 oranındadır', ['1/4 oranındadır', '1/6 oranındadır', '5/12 oranındadır'], 'Düzgün altıgenin bir kenarı a ise yüksekliği (AB ile EF arası uzaklık) a√3\'tür. EFM üçgeninin tabanı |EF|=a ve yüksekliği a√3 olduğundan alanı a²√3/2 olur. Altıgenin alanı 6·(a²√3/4) = 3a²√3/2 olduğundan oran (1/2)/(3/2) = 1/3\'tür.'),
  ('İki farklı düzgün çokgenden birincisinin kenar sayısı ikincisinin kenar sayısının 2 katıdır. Birinci çokgenin bir iç açısının ikinci çokgenin bir iç açısına oranı 5/4 olduğuna göre bu iki çokgenin kenar sayıları toplamı kaçtır?', '18 kenar eder', ['12 kenar eder', '15 kenar eder', '24 kenar eder'], 'İkinci çokgenin kenar sayısı n, birincininki 2n olsun. İç açılar oranı [(2n-2)/2n] / [(n-2)/n] = (n-1)/(n-2) = 5/4 olur. Buradan 4n - 4 = 5n - 10 ile n = 6 ve 2n = 12 bulunur; toplamları 6 + 12 = 18 eder.'),
  ('Ardışık A, B, C, D köşelerine sahip bir düzgün çokgende [AB ve [DC ışınları çokgenin dış bölgesindeki bir K noktasında kesişmektedir. BKC açısının ölçüsü 100 derece olduğuna göre çokgenin kenar sayısı kaçtır?', '9 kenara sahiptir', ['8 kenara sahiptir', '10 kenara sahiptir', '12 kenara sahiptir'], 'BKC üçgeninde B ve C köşelerindeki dar açılar düzgün çokgenin birer dış açısıdır (α). 2α + 100° = 180° eşitliğinden α = 40° ve kenar sayısı 360°/40° = 9 bulunur.'),
  ('ABCDE düzgün beşgeninin dış bölgesine, bir kenarı beşgenin [AB] kenarı ile ortak olacak biçimde ABKL karesi inşa ediliyor. E, A ve K noktalarının oluşturduğu AEK üçgeninde AEK açısı kaç derecedir?', '9 derecelik açıdır', ['12 derecelik açıdır', '15 derecelik açıdır', '18 derecelik açıdır'], 'A köşesi etrafında m(EAB) = 108° ve m(BAK) = 90° olduğundan üçgenin tepe açısı m(EAK) = 360° - (108° + 90°) = 162° olur. |EA| = |AB| = |AK| ikizkenarlığından m(AEK) = (180° - 162°)/2 = 9° bulunur.'),
  ('Bir konveks çokgenin kenar sayısı 2 artırıldığında toplam köşegen sayısının 15 arttığı gözleniyor. Başlangıçtaki çokgenin kenar sayısı kaçtır?', '8 kenarı vardır', ['6 kenarı vardır', '7 kenarı vardır', '9 kenarı vardır'], '(n+2)(n-1)/2 - n(n-3)/2 = 15 denkleminden [(n² + n - 2) - (n² - 3n)] = 30 yani 4n - 2 = 30 elde edilir; buradan n = 8 bulunur.'),
  ('Çevrel çemberinin yarıçapı 4 santimetre olan bir düzgün sekizgende, aralarında bir köşe bırakılarak seçilen A ve C köşelerini birleştiren [AC] köşegeninin uzunluğu kaç santimetredir?', '4√2 santimetre', ['4√3 santimetre', '6 santimetre', '2√6 santimetre'], 'Düzgün sekizgende her kenar 360°/8 = 45° merkez açı görür. İki kenar gören [AC] kirişi merkezde 90° açı oluşturduğundan ikizkenar dik üçgenden |AC| = 4√2 cm olur.'),
  ('Kenar uzunluğu 6 santimetre olan ABCDEFGH düzgün sekizgeninde ardışık A, B ve C köşelerinin birleştirilmesiyle oluşan ABC üçgeninin alanı kaç santimetrekaredir?', '9√2 santimetrekare', ['9√3 santimetrekare', '12√2 santimetrekare', '18 santimetrekare'], 'Düzgün sekizgenin bir iç açısı m(ABC) = 135° ve |AB| = |BC| = 6 cm\'dir. Sinüs alan formülünden Alan(ABC) = (1/2)·6·6·sin135° = 18·(√2/2) = 9√2 cm² bulunur.'),
  ('Kağıttan kesilmiş bir ABCDEF düzgün altıgeni [AC] köşegeni boyunca katlandığında B köşesinin altıgen düzlemi üzerinde çakıştığı yeni nokta neresidir?', 'Altıgenin ağırlık ve çevrel çember merkezi', ['Karşıdaki [EF] kenarının tam orta noktası', '[AD] ana köşegeninin D ucuna yakın çeyrek noktası', '[CF] köşegeni ile [BE] köşegeninin dışındaki bölge'], 'Düzgün altıgende merkez O olmak üzere OABC dörtgeninin tüm kenarları yarıçapa (a) eşit bir eşkenar dörtgendir. Köşegen [AC], B ile O\'yu birbirine göre dik ve eşit uzaklıkta tuttuğundan B noktası tam O merkezine katlanır.'),
  ('Bir düzgün altıgen kağıdın B, D ve F köşeleri sırasıyla [AC], [CE] ve [EA] köşegenleri boyunca içe doğru katlandığında elde edilen yeni çokgensel yüzeyin alanı başlangıçtaki altıgen alanının kaçta kaçı olur?', 'Tam yarısı (1/2) olur', ['Üçte biri (1/3) olur', 'Üçte ikisi (2/3) olur', 'Dörtte üçü (3/4) olur'], 'Katlanan ABC, CDE ve EFA üçgenleri altıgenin merkezinde birleşerek ACE eşkenar üçgeninin üzerini tam kaplar; tek katlı silüet ACE eşkenar üçgeni olup alanı altıgenin alanının 1/2\'sidir.'),
  ('Düzgün beşgen yıldız (pentagram) şeklindeki bir rozetin beş sivri ucundaki dar iç açıların ölçüleri toplamı kaç derecedir?', '180 dereceye eşittir', ['108 dereceye eşittir', '270 dereceye eşittir', '360 dereceye eşittir'], 'Düzgün beşgenin köşegenleriyle oluşan yıldızın her bir sivri ucundaki çevre açı çemberin beşte birlik (72°) yayını gördüğünden 36°\'dir; 5 × 36° = 180° eder.'),
  ('Yarı düzgün bir mozaik deseninde her düğüm noktasında bir adet düzgün altıgen ile kenar uzunlukları aynı olan belirli sayıda eşkenar üçgen boşluksuz birleşmektedir. Bir düğüm noktasında kaç eşkenar üçgen yer alır?', '4 adet eşkenar üçgen', ['2 adet eşkenar üçgen', '3 adet eşkenar üçgen', '5 adet eşkenar üçgen'], 'Bir köşe etrafındaki tam açı 360°\'dir. Bir düzgün altıgen 120° yer kapladığından geriye 360° - 120° = 240° kalır; her eşkenar üçgenin açısı 60° olduğundan 240°/60° = 4 eşkenar üçgen gerekir.'),
  ('Düzgün onikigen şeklindeki büyük karoların arasına, boşluk kalmaması için aynı kenar uzunluğuna sahip hangi düzgün çokgen karolar tek başına yerleştirilebilir?', 'Eşkenar üçgen karolar', ['Kare biçimli karolar', 'Düzgün beşgen karolar', 'Düzgün altıgen karolar'], 'Düzgün onikigenin bir iç açısı 150°\'dir. İki onikigen bir köşede birleştiğinde 150° + 150° = 300° oluşturur; kalan 60°\'lik boşluğu tam olarak bir eşkenar üçgen doldurur.'),
  ('A1, A2, ..., A10 ardışık köşelere sahip bir düzgün ongende A1 köşesini A4 ve A8 köşelerine bağlayan kirişlerin oluşturduğu A4A1A8 açısı kaç derecedir?', '72 derecelik çevre açıdır', ['54 derecelik çevre açıdır', '60 derecelik çevre açıdır', '36 derecelik çevre açıdır'], 'Düzgün ongenin çevrel çemberinde her kenar 36° yay görür. A4 ile A8 arasında (8 - 4 = 4 kenarlık) 4 × 36° = 144° yay vardır; bunu gören A4A1A8 çevre açısı 144°/2 = 72° olur.'),
  ('Bir ABCDE düzgün beşgeninde [AC] ve [BD] köşegenleri K noktasında kesişmektedir. |AK| uzunluğu 4 birim olarak ölçüldüğüne göre beşgenin çevresi kaç birimdir?', '20 birimdir', ['16 birimdir', '10√5 birimdir', '24 birimdir'], 'Düzgün beşgende [AC] // [ED] ve [BD] // [AE] olduğundan AKDE dörtgeni bir eşkenar dörtgendir. Dolayısıyla beşgenin bir kenarı |AE| = |AK| = 4 birim olup çevresi 5 × 4 = 20 birimdir.'),
  ('Bir kenarı 4√3 santimetre olan ABCDEF düzgün altıgeninin her kenarının orta noktası ardışık olarak birleştirilerek yeni bir altıgen elde ediliyor. Yeni oluşan içteki altıgenin çevresi kaç santimetredir?', '36 santimetredir', ['24√3 santimetredir', '18√3 santimetredir', '30 santimetredir'], 'Komşu iki kenarın orta noktalarını birleştiren doğru parçası, tepe açısı 120° ve yan kenarları 2√3 cm olan ikizkenar üçgenin tabanıdır. 30°-30°-120° özelliğinden yeni kenar 2√3·√3 = 6 cm, çevre ise 6 × 6 = 36 cm olur.'),
  ('ABCDEF düzgün altıgeninde [AD] ana köşegeni üzerinde |AP| = 2 birim ve |PD| = 6 birim olacak biçimde bir P noktası işaretleniyor. Altıgenin B köşesinin P noktasına uzaklığı kaç birimdir?', '2√3 birim uzunluğundadır', ['3√2 birim uzunluğundadır', '4 birim uzunluğundadır', '√13 birim uzunluğundadır'], 'Ana köşegen |AD| = 2 + 6 = 8 birim olduğundan altıgenin bir kenarı |AB| = 4 birimdir. [AD] simetri ekseni 120°\'lik A açısını ikiye böler: m(BAP) = 60°. BAP üçgeninde |AB|=4, |AP|=2 ve aradaki açı 60° olduğundan 30°-60°-90° üçgeni oluşur ve |BP| = 2√3 bulunur.'),
  ('Bir konveks çokgenin dört iç açısının ölçüleri 100°, 110°, 130° ve 140° olarak biliniyor. Diğer tüm iç açıları birbirine eşit ve 165° olduğuna göre çokgenin kaç köşesi vardır?', '12 köşesi vardır', ['10 köşesi vardır', '11 köşesi vardır', '14 köşesi vardır'], 'İlk dört köşenin dış açıları 80°, 70°, 50° ve 40° olup toplamı 240° eder. Geriye 360° - 240° = 120° kalır; diğer köşelerin dış açısı 180° - 165° = 15° olduğundan 120°/15° = 8 köşe daha bulunur ve toplam 4 + 8 = 12 köşe elde edilir.'),
  ('Ardışık köşeleri ABCDEFGH biçiminde sıralanan bir düzgün sekizgende [AD] köşegeni ile [DE] kenarı arasındaki ADE açısının ölçüsü kaç derecedir?', '90 derecelik dik açıdır', ['67,5 derecelik dar açıdır', '112,5 derecelik geniş açıdır', '135 derecelik geniş açıdır'], 'Çevrel çemberde A ile E köşeleri arasında 4 kenar (4 × 45° = 180°) bulunduğu için [AE] çaptır; çapı gören ADE çevre açısı Thales teoremi gereği 90° olur.'),
  ('Kağıttan yapılmış dışbükey bir çokgen, yalnız bir köşegeni boyunca düz bir makasla kesildiğinde bir adet beşgen ve bir adet sekizgen parçaya ayrılıyor. Kesilmeden önceki çokgen kaç kenarlıydı?', '11 kenarlı bir çokgendi', ['12 kenarlı bir çokgendi', '13 kenarlı bir çokgendi', '10 kenarlı bir çokgendi'], 'Köşegen boyunca yapılan kesim mevcut kenarları bölmez, yalnızca iki parçanın da paylaştığı 1 yeni kenar (kesim çizgisi) üretir: n + 2 = 5 + 8 eşitliğinden n = 11 bulunur.'),
  ('ABCDE düzgün beşgeninde [AC] ve [BE] köşegenleri F noktasında kesişmektedir. Oluşan EFCD dörtgeninin komşu iki kenarının uzunlukları toplamı |EF| + |FC| = 14 santimetre ise beşgenin çevresi kaç santimetredir?', '35 santimetre', ['28 santimetre', '42 santimetre', '70 santimetre'], 'Düzgün beşgende [BE] // [CD] ve [AC] // [ED] olup |CD| = |ED| olduğundan EFCD dörtgeni eşkenar dörtgendir. |EF| = |FC| = 7 cm beşgenin bir kenarına eşittir; çevre 5 × 7 = 35 cm olur.'),
  ('Düzgün ondörtgenin köşelerinden herhangi üçü seçilerek oluşturulabilecek üçgenlerden kaç tanesi dik üçgendir?', '84 adet dik üçgen', ['70 adet dik üçgen', '91 adet dik üçgen', '42 adet dik üçgen'], 'Çevrel çemberde dik üçgen oluşması için hipotenüsün çap olması gerekir. 14 köşe 7 farklı çap belirler; her çap geriye kalan 12 köşeyle 12 dik üçgen ürettiğinden 7 × 12 = 84 dik üçgen oluşur.'),
  ('Köşeleri bir düzgün onbirgenin köşeleri arasından seçilen üçgenlerin kaç tanesi dik üçgen özelliğine sahiptir?', 'Hiçbiri dik üçgen olamaz', ['11 adet dik üçgen oluşur', '22 adet dik üçgen oluşur', '55 adet dik üçgen oluşur'], 'Tek sayıda köşesi olan düzgün çokgenlerin çevrel çemberinde karşılıklı iki köşeyi birleştiren hiçbir kiriş merkezden (çaptan) geçmez; dolayısıyla 90° çevre açı oluşamaz.'),
  ('Kenar uzunluğu 6 birim olan bir düzgün altıgenin her bir kenarı üzerine dış bölgeye doğru birer eşkenar üçgen inşa edilerek altı köşeli yıldız (heksagram) elde ediliyor. Yıldızın toplam alanı kaç birimkaredir?', '108√3 birimkaredir', ['72√3 birimkaredir', '96√3 birimkaredir', '144√3 birimkaredir'], 'Düzgün altıgenin kendisi kenarı 6 birim olan 6 eşkenar üçgenden oluşur; dışarıya eklenen 6 eşkenar üçgenle birlikte toplam 12 eşkenar üçgen elde edilir: 12 × (6²√3 / 4) = 108√3 birimkare.'),
  ('Çevrel çemberinin yarıçapı 6 santimetre olan bir düzgün sekizgenin kapladığı düzlemsel alan kaç santimetrekaredir?', '72√2 santimetrekaredir', ['36√2 santimetrekaredir', '72√3 santimetrekaredir', '108 santimetrekaredir'], 'Merkezden köşelere çizilen yarıçaplar sekizgeni tepe açısı 45° olan 8 eş ikizkenar üçgene ayırır: 8 × (1/2 · 6 · 6 · sin45°) = 144 · (√2/2) = 72√2 cm².'),
  ('Alanı 72 santimetrekare olan ABCDEF düzgün altıgeninde [DE] kenarının orta noktası M, [EF] kenarının orta noktası N olarak işaretleniyor. Köşeleri M, E ve N olan üçgenin alanı kaç santimetrekaredir?', '3 santimetrekaredir', ['4 santimetrekaredir', '6 santimetrekaredir', '9 santimetrekaredir'], 'DEF üçgeninin alanı altıgen alanının altıda birine yani 72/6 = 12 cm²\'ye eşittir. MEN üçgeninde kenarlar yarıya indiği için benzerlik oranının karesinden (1/2)² = 1/4 gelir; alan 12/4 = 3 cm² olur.'),
  ('Bir iç açısının ölçüsü 168 derece olan düzgün çokgenin simetri eksenlerinden kaç tanesi karşılıklı kenarların orta noktalarından geçer?', '15 simetri ekseni', ['30 simetri ekseni', '12 simetri ekseni', '24 simetri ekseni'], 'Dış açısı 180° - 168° = 12° olan çokgen 360°/12° = 30 kenarlıdır (çift kenarlı). 30 simetri ekseninin yarısı karşılıklı köşelerden, diğer yarısı olan 15 tanesi karşılıklı kenar ortalarından geçer.'),
  ('Kenar uzunluğu 2 birim olan ABCDEF düzgün altıgeninde A köşesi ile [CD] kenarının orta noktası olan M arasındaki doğrusal uzaklık kaç birimdir?', '√13 birim uzaklıktadır', ['√11 birim uzaklıktadır', '2√3 birim uzaklıktadır', '√15 birim uzaklıktadır'], '[AD] çap olduğundan m(ACD) = 90° ve kısa köşegen |AC| = 2√3 birimdir. |CM| = 1 birim olduğundan ACM dik üçgeninde Pisagor teoreminden |AM| = √((2√3)² + 1²) = √13 birim bulunur.'),
  ('Çevrel çemberinin yarıçapı 8 birim olan A1A2...A12 düzgün onikigeninde A1 ile A5 köşelerini birleştiren köşegenin uzunluğu kaç birimdir?', '8√3 birimdir', ['8√2 birimdir', '12 birimdir', '16 birimdir'], 'Düzgün onikigende her kenar 30° merkez açı görür; A1 ile A5 arasındaki 4 kenar 120° merkez açı oluşturur. Yarıçapları 8 birim olan 30°-30°-120° üçgeninden kiriş uzunluğu 8√3 birim bulunur.'),
  ('Bir düzlem köşesinde aralarında hiç açısal boşluk kalmayacak biçimde bir adet kare ve bir adet düzgün yirmigen ile birlikte üçüncü bir düzgün çokgen birleştiriliyor. Üçüncü düzgün çokgen aşağıdakilerden hangisidir?', 'Düzgün beşgen', ['Düzgün altıgen', 'Düzgün sekizgen', 'Düzgün ongen'], 'Karenin iç açısı 90°, düzgün yirmigenin iç açısı 180° - (360°/20) = 162°\'dir. Tam açıdan çıkarıldığında 360° - (90° + 162°) = 108° kalır ki bu da düzgün beşgenin bir iç açısıdır.'),
  ('Bir dışbükey dörtgenin kenar orta noktalarının birleştirilmesiyle oluşan Varignon paralelkenarının bir eşkenar dörtgen olabilmesi için başlangıçtaki dörtgenin köşegenleri hangi özelliği taşımalıdır?', 'Köşegen uzunlukları birbirine eşit olmalıdır', ['Köşegenler birbirini dik açıyla kesmelidir', 'Köşegenler birbirini tam ortadan bölmelidir', 'Köşegenler iç açıların açıortayı olmalıdır'], 'Varignon paralelkenarının komşu kenarları ana dörtgenin köşegenlerinin yarısına (e/2 ve f/2) eşittir; bu kenarların eşit olup eşkenar dörtgen oluşturması e = f koşuluna bağlıdır.'),
  ('Köşegenleri dik kesişen konveks bir ABCD dörtgeninde |AB| = 5 birim, |BC| = 8 birim ve |CD| = 9 birim olarak veriliyor. Buna göre dördüncü kenar olan |DA| kaç birimdir?', '√42 birim uzunluğundadır', ['√38 birim uzunluğundadır', '6 birim uzunluğundadır', '√46 birim uzunluğundadır'], 'Köşegenleri dik kesişen dörtgenlerde karşılıklı kenarların kareleri toplamı birbirine eşittir: |AB|² + |CD|² = |BC|² + |DA|² => 25 + 81 = 64 + |DA|² => |DA|² = 42 ve |DA| = √42 birim olur.'),
  ('Dışbükey bir ABCD dörtgeninde karşılıklı A ve C köşelerinden çizilen iç açıortayların kesişimiyle oluşan dar açı 23 derece olarak ölçülüyor. D açısının ölçüsü 132 derece ise B açısının alabileceği küçük değer kaç derecedir?', '86 derece değerini alır', ['92 derece değerini alır', '109 derece değerini alır', '78 derece değerini alır'], 'Karşılıklı iki açıortay arasındaki dar açı |m(D) - m(B)| / 2 bağıntısıyla bulunur: (132° - m(B))/2 = 23° => 132° - m(B) = 46° => m(B) = 86° elde edilir.'),
  ('ABCD dörtgeninde köşegenler dik kesişmekte, ancak [BD] köşegeni dörtgenin dış bölgesinde kalan içbükey bir yapı oluşturmaktadır. |AB| = 7 cm, |BC| = 4 cm ve |CD| = 6 cm ise |AD| uzunluğu kaç santimetredir?', '√69 santimetre uzunluğundadır', ['√53 santimetre uzunluğundadır', '8 santimetre uzunluğundadır', '√61 santimetre uzunluğundadır'], 'Köşegen doğrultuları dik kesişen içbükey dörtgenlerde de karşılıklı kenarların kareleri toplamı eşitliği korunur: 7² + 6² = 4² + |AD|² => 49 + 36 = 16 + |AD|² => |AD| = √69 cm.'),
  ('Paralel tabanlarının uzunlukları 5 metre ve 13 metre olan ikizkenar yamuk biçimindeki bir çatı yüzeyi, birbirini dik kesen iki çelik köşegen profille desteklenmiştir. Bu çatının yüksekliği kaç metredir?', '9 metre yüksekliğindedir', ['8 metre yüksekliğindedir', '√65 metre yüksekliğindedir', '6,5 metre yüksekliğindedir'], 'Köşegenleri dik kesişen bir ikizkenar yamukta yükseklik, paralel tabanların aritmetik ortalamasına (orta taban uzunluğuna) eşittir: h = (5 + 13) / 2 = 9 metre.'),
  ('[AB] // [DC] ve [AD] ⊥ [AB] koşullarını sağlayan bir ABCD dik yamuğunda [AC] ve [BD] köşegenleri birbirini dik kesmektedir. Üst taban |DC| = 4 birim ve alt taban |AB| = 9 birim ise dik kenar |AD| kaç birimdir?', '6 birim yüksekliğindedir', ['6,5 birim yüksekliğindedir', '5 birim yüksekliğindedir', '2√13 birim yüksekliğindedir'], 'Köşegenleri dik kesişen bir dik yamukta Öklid benzerliğinden yüksekliğin karesi alt ve üst tabanların çarpımına eşittir: h² = 4 × 9 = 36 => h = |AD| = 6 birim.'),
  ('Bir ABCD yamuğunda [AB] // [DC] olup köşegenler E noktasında kesişmektedir. Üst tabana komşu DEC üçgeninin alanı 9 birimkare, alt tabana komşu AEB üçgeninin alanı 25 birimkare ise yamuğun toplam alanı kaç birimkaredir?', '64 birimkare alana sahiptir', ['58 birimkare alana sahiptir', '49 birimkare alana sahiptir', '68 birimkare alana sahiptir'], 'Yamukta yan kanat üçgenlerinin (AED ve BEC) alanları birbirine eşit ve √(9 × 25) = 15 birimkaredir. Tüm yamuğun alanı 9 + 25 + 15 + 15 = 64 birimkare olur.'),
  ('[AB] // [DC] olan bir ABCD yamuğunda A ve D köşelerine ait iç açıortaylar K noktasında kesişmektedir. Yan kenar |AD| = 14 santimetre olduğuna göre K noktasının [AD] kenarının orta noktasına olan uzaklığı kaç santimetredir?', '7 santimetre uzaklıktadır', ['3,5 santimetre uzaklıktadır', '7√2 santimetre uzaklıktadır', '5 santimetre uzaklıktadır'], 'Paralel doğrular arasında kalan A ve D açılarının toplamı 180° olduğundan açıortaylar K noktasında dik (90°) kesişir. AKD dik üçgeninde hipotenüse ait kenarortay (muhteşem üçlü) |AD|/2 = 7 cm\'dir.'),
  ('İkizkenar bir ABCD yamuğunda [AB] // [DC], yan kenarlar |AD| = |BC| = 10 birim, üst taban |DC| = 8 birim ve alt taban |AB| = 20 birimdir. Bu yamuğun bir köşegeninin uzunluğu kaç birimdir?', '2√65 birimdir', ['16 birimdir', '4√13 birimdir', '2√41 birimdir'], 'C köşesinden [AB] tabanına dikme indirildiğinde sağda (20 - 8)/2 = 6 birimlik parça ayrılır; 6-8-10 üçgeninden yükseklik h = 8 birimdir. Solda kalan parça 20 - 6 = 14 birim olduğundan |AC| = √(14² + 8²) = √260 = 2√65 birim bulunur.'),
  ('Bir ABCD yamuğunda [AB] // [DC] olup [BC] yan kenarının orta noktası M olarak işaretleniyor. M noktasının [AD] kenarına olan dik uzaklığı 7 santimetre ve |AD| = 12 santimetre olduğuna göre yamuğun alanı kaç santimetrekaredir?', '84 santimetrekare', ['42 santimetrekare alana sahiptir', '72 santimetrekare alana sahiptir', '96 santimetrekare'], 'Yamukta bir yan kenarın orta noktasını karşı yan kenarın uçlarına birleştiren ADM üçgeninin alanı tüm yamuğun alanının yarısıdır. Alan(ADM) = (12 × 7)/2 = 42 cm² olduğundan yamuğun alanı 2 × 42 = 84 cm² bulunur.'),
  ('Paralel tabanları |DC| = 6 birim ve |AB| = 12 birim olan bir ABCD yamuğunda köşegenlerin kesim noktasından geçen ve tabanlara paralel uzanan doğru parçasının yamuk içinde kalan kısmının uzunluğu kaç birimdir?', '8 birimdir', ['9 birim uzunluğundadır', '7,5 birim uzunluğundadır', '10 birim uzunluğundadır'], 'Yamukta köşegenlerin kesim noktasından tabanlara paralel çizilen doğru parçasının uzunluğu alt ve üst tabanın harmonik ortalamasıdır: 2·a·c / (a + c) = (2 × 12 × 6) / (12 + 6) = 144 / 18 = 8 birim.'),
  ('[AB] // [DC] olan bir ABCD yamuğunda m(A) = 70° ve m(B) = 55° olarak verilmiştir. Yan kenar |BC| = 9 birim ve üst taban |DC| = 4 birim olduğuna göre alt taban |AB| kaç birimdir?', '13 birimdir', ['12 birim uzunluğundadır', '14 birim uzunluğundadır', '15 birim uzunluğundadır'], 'C köşesinden [AD] kenarına paralel çizilerek [AB] üzerinde K noktası alındığında ADCK paralelkenar olur ve |AK| = 4 birim, m(CKB) = 70° bulunur. CKB üçgeninde m(KCB) = 180° - (70° + 55°) = 55° olduğundan |KB| = |BC| = 9 birim ve |AB| = 4 + 9 = 13 birimdir.'),
  ('İkizkenar bir ABCD yamuğunda [AB] // [DC] olup C köşesinden [AB] tabanına indirilen dikme ayağı H noktasıdır. |AH| = 11 birim ve yamuğun yüksekliği |CH| = 8 birim olduğuna göre bu yamuğun yüzey alanı kaç birimkaredir?', '88 birimkare', ['44 birimkare alana sahiptir', '96 birimkare alana sahiptir', '110 birimkare'], 'İkizkenar yamukta üst köşeden tabana inen dikmenin uzun kenar tarafında ayırdığı |AH| parçası doğrudan orta taban uzunluğuna ((a + c)/2) eşittir. Alan = |AH| × |CH| = 11 × 8 = 88 birimkare bulunur.'),
  ('Kenar uzunlukları |AB| = 15 santimetre ve |AD| = 9 santimetre olan bir ABCD paralelkenarında A ve B köşelerine ait iç açıortaylar [DC] kenarı veya uzantısı yerine paralelkenarın iç bölgesine yakın biçimde kesişerek D ve C yönüne uzatıldığında [DC] doğrusu üzerinde ayırdıkları parçanın uzunluğu kaç santimetredir?', '3 santimetre', ['6 santimetre uzunluğundadır', '4,5 santimetre uzunluğundadır', '7,5 santimetre'], 'A açıortayı [DC] üzerinde |DE| = |AD| = 9 cm, B açıortayı ise |CF| = |BC| = 9 cm ayırır. |DC| = 15 cm olduğundan iki parçanın üst üste binen ortak kısmı |EF| = (9 + 9) - 15 = 3 cm olur.'),
  ('ABCD paralelkenarında A köşesinden [BC] kenarına indirilen dikmenin uzunluğu 6 birim, [DC] kenarına indirilen dikmenin uzunluğu ise 10 birimdir. Paralelkenarın çevresi 64 birim olduğuna göre alanı kaç birimkaredir?', '120 birimkare', ['96 birimkare alana sahiptir', '144 birimkare alana sahiptir', '150 birimkare'], '|AB| = a ve |BC| = b denirse a + b = 32 birimdir. Alan eşitliğinden 10·a = 6·b => 5a = 3b yazılır; a = 3k ve b = 5k seçildiğinde 8k = 32 => k = 4, yani a = 12 birim ve Alan = 12 × 10 = 120 birimkare bulunur.'),
  ('Kenar uzunlukları 7 birim ve 9 birim olan bir paralelkenarın uzun köşegeni 14 birim olarak ölçülmüştür. Bu paralelkenarın kısa köşegeninin uzunluğu kaç birimdir?', '8 birimdir', ['6√2 birim uzunluğundadır', '4√3 birim uzunluğundadır', '10 birimdir'], 'Paralelkenarda köşegenlerin kareleri toplamı kenarların kareleri toplamının iki katına eşittir: e² + f² = 2(a² + b²) => 14² + f² = 2(49 + 81) => 196 + f² = 260 => f² = 64 ve f = 8 birim olur.'),
  ('Alanı 96 santimetrekare olan bir ABCD paralelkenarında [DC] kenarının orta noktası E, [BC] kenarının orta noktası F olarak işaretleniyor. Köşeleri A, E ve F olan üçgenin alanı kaç santimetrekaredir?', '36 santimetrekare', ['32 santimetrekare alana sahiptir', '40 santimetrekare alana sahiptir', '48 santimetrekare'], 'Tüm alan 8S = 96 cm² (S = 12 cm²) olarak ölçeklenirse: Alan(ADE) = 2S, Alan(ABF) = 2S ve köşedeki Alan(ECF) = S olur. Ortada kalan Alan(AEF) = 8S - (2S + 2S + S) = 3S = 36 cm² bulunur.'),
  ('ABCD paralelkenarında [DC] ve [BC] kenarlarının orta noktaları olan M ve N noktaları A köşesine birleştiriliyor. Çizilen [AM] ve [AN] doğru parçaları paralelkenarın [BD] köşegenini hangi oranda parçalara ayırır?', 'Üç birbirine eşit parçaya ayırır', ['1 : 2 : 1 oranında parçalara ayırır', '2 : 1 : 2 oranında parçalara ayırır', 'Yalnızca iki eş parçaya ayırır'], '[AC] köşegeni çizildiğinde kesim noktası O olmak üzere [AM] ve [AN] sırasıyla ACD ve ABC üçgenlerinin kenarortaylarıdır; ağırlık merkezleri |BD| köşegenini |DP| = |PQ| = |QB| olacak biçimde tam 3 eş parçaya böler.'),
  ('ABCD paralelkenarının düzleminde fakat dış bölgesinden geçen bir d doğrusuna A, B ve C köşelerinden indirilen dikmelerin uzunlukları sırasıyla 5 cm, 12 cm ve 19 cm olarak ölçülmüştür. D köşesinden aynı d doğrusuna indirilen dikmenin uzunluğu kaç santimetredir?', '12 santimetre', ['14 santimetre uzunluğundadır', '10 santimetre uzunluğundadır', '16 santimetre'], 'Paralelkenarın köşegenlerinin orta noktaları çakışık olduğundan, dışarıdaki bir doğruya karşılıklı köşelerden indirilen dikmelerin toplamları birbirine eşittir: hA + hC = hB + hD => 5 + 19 = 12 + hD => hD = 12 cm.'),
  ('Bir ABCD paralelkenarında [AD] kenarının uzantısı üzerinde D noktasından sonra |DF| = |AD| olacak biçimde bir F noktası alınıyor. [FB] doğru parçası [DC] kenarını K noktasında kestiğine göre Alan(DKF) = 7 birimkare ise paralelkenarın alanı kaç birimkaredir?', '28 birimkare', ['21 birimkare alana sahiptir', '35 birimkare alana sahiptir', '42 birimkare'], '[DK] // [AB] ve |FD| = |DA| olduğundan [DK], FAB üçgeninin orta tabanıdır; |DK| = |KC| olur. Eş üçgenlerden Alan(CBK) = Alan(DKF) = 7 br² ve yamuk kısmından Alan(ABKD) = 3 × 7 = 21 br² olup paralelkenarın alanı 21 + 7 = 28 br² bulunur.'),
  ('Köşegen uzunlukları 12 birim ve 16 birim olan bir eşkenar dörtgenin paralel iki kenarı arasındaki dik uzaklık (yüksekliği) kaç birimdir?', '9,6 birimdir', ['8,4 birim yüksekliğindedir', '9,2 birim yüksekliğindedir', '10 birimdir'], 'Yarı köşegenler 6 ve 8 birim olduğundan bir kenar 6-8-10 üçgeninden a = 10 birimdir. Eşkenar dörtgenin alanı (12 × 16)/2 = 96 birimkare olup a·h = 96 => 10·h = 96 => h = 9,6 birim elde edilir.'),
  ('Dar açısının ölçüsü 60 derece olan bir ABCD eşkenar dörtgeninin içine tüm kenarlarına teğet olacak biçimde yerleştirilen iç teğet çemberin yarıçapı 3√3 santimetredir. Eşkenar dörtgenin çevresi kaç santimetredir?', '48 santimetre', ['36 santimetre çevreye sahiptir', '24√3 santimetre çevreye sahiptir', '60 santimetre'], 'İç teğet çemberin çapı eşkenar dörtgenin yüksekliğine eşittir: h = 2 × 3√3 = 6√3 cm. Dar açısı 60° olduğundan 30°-60°-90° üçgeninden bir kenar a = 6√3 / (√3/2) = 12 cm ve çevre 4 × 12 = 48 cm bulunur.'),
  ('Bir ABCD eşkenar dörtgeninde B köşesinden [AD] ve [DC] kenarlarına indirilen dikmeler bu iki kenarı da tam ortalarından ikiye bölmektedir. Buna göre eşkenar dörtgenin geniş açısı olan ABC açısı kaç derecedir?', '120 derece', ['108 derece ölçüsündedir', '135 derece ölçüsündedir', '150 derece'], 'B köşesinden [AD] kenarına inen dikme aynı zamanda kenarortay olduğundan |BA| = |BD| ikizkenarlığı doğar; zaten |BA| = |AD| olduğundan ABD eşkenar üçgen olur ve m(A) = 60°, bütünleri olan m(ABC) = 120° bulunur.'),
  ('Kenarları 15 santimetre olan bir ABCD eşkenar dörtgeninde [AC] köşegeni üzerinde |AE| = 4 cm ve |EC| = 14 cm olacak biçimde bir E noktası alınıyor. E noktasının D köşesine olan uzaklığı |DE| kaç santimetredir?', '13 santimetre', ['11 santimetre uzunluğundadır', '12 santimetre uzunluğundadır', '14 santimetre'], '|AC| = 4 + 14 = 18 cm olup köşegenlerin dik kesim noktası O için |AO| = |OC| = 9 cm ve |EO| = 9 - 4 = 5 cm bulunur. AOD dik üçgeninde (9-12-15) |DO| = 12 cm olduğundan EOD dik üçgeninde 5-12-13 üçgeninden |DE| = 13 cm elde edilir.'),
  ('Bir ABC dik üçgeninde [AB] ⊥ [BC], |AB| = 6 birim ve |BC| = 12 birimdir. Köşeleri üçgenin kenarları üzerinde bulunan (D ∈ [AC], E ∈ [BC], F ∈ [AB]) BEDF eşkenar dörtgeninin bir kenar uzunluğu kaç birimdir?', '4 birimdir', ['3 birim uzunluğundadır', '4,5 birim uzunluğundadır', '3√2 birimdir'], 'Eşkenar dörtgenin bir kenarına x denirse [FD] // [BC] benzerliğinden |AF| / |AB| = |FD| / |BC| => (6 - x) / 6 = x / 12 => 12 - 2x = x => 3x = 12 ve x = 4 birim bulunur.'),
  ('Köşegenlerinin uzunlukları toplamı 28 santimetre ve bir kenar uzunluğu 10 santimetre olan bir eşkenar dörtgenin alanı kaç santimetrekaredir?', '96 santimetrekare', ['84 santimetrekare alana sahiptir', '92 santimetrekare alana sahiptir', '108 santimetrekare'], 'Köşegenler e ve f ise e + f = 28 ve dik kesişmeden (e/2)² + (f/2)² = 10² => e² + f² = 400 olur. (e + f)² = 784 => e² + f² + 2ef = 784 => 2ef = 384 => Alan = ef / 2 = 384 / 4 = 96 cm² elde edilir.'),
  ('ABCD dikdörtgeninin iç bölgesinde seçilen bir P noktasının A, B ve C köşelerine olan uzaklıkları sırasıyla |PA| = 4 cm, |PB| = 7 cm ve |PC| = 9 cm\'dir. Buna göre P noktasının D köşesine uzaklığı |PD| kaç santimetredir?', '4√3 santimetre', ['6 santimetre uzunluğundadır', '5√2 santimetre uzunluğundadır', '√52 santimetre'], 'İngiliz Bayrağı Teoremi gereği dikdörtgen düzlemindeki her P noktası için karşılıklı köşelere olan uzaklıkların kareleri toplamı eşittir: |PA|² + |PC|² = |PB|² + |PD|² => 16 + 81 = 49 + |PD|² => |PD|² = 48 ve |PD| = 4√3 cm olur.'),
  ('ABCD dikdörtgeninde [DE] ⊥ [AC] (E ∈ [AC]) ve B köşesinden [AC]\'ye indirilen dikme ayağı F noktasıdır. |AE| = 3 birim ve |EF| = 5 birim olduğuna göre dikdörtgenin kısa kenarı |AD| kaç birimdir?', '√33 birimdir', ['6 birim uzunluğundadır', '2√6 birim uzunluğundadır', '√39 birimdir'], 'Simetri ve eş üçgenlerden (ADE ≅ CBF) |FC| = |AE| = 3 birim olur; böylece tüm köşegen |AC| = 3 + 5 + 3 = 11 birimdir. ADC dik üçgeninde Öklid dik kenar bağıntısından |AD|² = |AE|·|AC| = 3 × 11 = 33 => |AD| = √33 birim bulunur.'),
  ('ABCD dikdörtgeninde E noktası [DC] kenarı üzerinde bir nokta ve m(AEB) = 90° olarak veriliyor. |DE| = 4 cm ve |EC| = 9 cm olduğuna göre dikdörtgenin çevresi kaç santimetredir?', '38 santimetre', ['36 santimetre çevreye sahiptir', '42 santimetre çevreye sahiptir', '44 santimetre'], 'ADE ve ECB dik üçgenleri benzerdir (açı-açı); |AD| = |BC| = h denirse h / 4 = 9 / h => h² = 36 => h = 6 cm bulunur. Uzun kenar |DC| = 4 + 9 = 13 cm olduğundan çevre 2 × (13 + 6) = 38 cm olur.'),
  ('Bir ABCD karesinin iç bölgesine [AB] kenarını taban kabul eden ABE eşkenar üçgeni çiziliyor. E noktasını D ve C köşelerine birleştiren doğru parçalarının oluşturduğu DEC açısının ölçüsü kaç derecedir?', '150 derece', ['135 derece ölçüsündedir', '140 derece ölçüsündedir', '165 derece'], 'm(DAE) = 90° - 60° = 30° ve |AD| = |AB| = |AE| ikizkenarlığından m(ADE) = (180° - 30°)/2 = 75° olur; m(EDC) = 90° - 75° = 15° ve simetriden m(ECD) = 15° olduğundan DEC üçgeninde tepe açısı 180° - 30° = 150° bulunur.'),
  ('ABCD karesinin dış bölgesine [BC] kenarı üzerine bir BCE eşkenar üçgeni inşa ediliyor. Karenin D köşesini eşkenar üçgenin E tepe noktasına bağlayan [DE] doğru parçası ile [DC] kenarı arasındaki CDE açısı kaç derecedir?', '15 derecedir', ['20 derece ölçüsündedir', '22,5 derece ölçüsündedir', '30 derecedir'], 'm(DCE) = 90° + 60° = 150° olup |CD| = |CB| = |CE| eşitliğinden CDE üçgeni ikizkenardır; taban açısı m(CDE) = (180° - 150°) / 2 = 15° bulunur.'),
  ('ABCD karesinde E ∈ [BC] ve F ∈ [CD] noktaları |BE| = |CF| koşulunu sağlayacak biçimde seçiliyor. [AE] ve [BF] doğru parçalarının kesim noktası K olduğuna göre AKB açısının ölçüsü kaç derecedir?', '90 derecedir', ['75 derece ölçüsündedir', '60 derece ölçüsündedir', '105 derecedir'], 'ABE ve BCF dik üçgenlerinde |AB| = |BC|, m(B) = m(C) = 90° ve |BE| = |CF| olduğundan iki üçgen KAK eşliğine sahiptir. m(BAE) = m(CBF) = α ve m(AEB) = 90° - α olduğundan AKB üçgeninde α + (90° - α) + m(AKB) = 180° => m(AKB) = 90° olur.'),
  ('Hipotenüs uzunluğu yerine dik kenarları |AB| = 12 cm ve |BC| = 18 cm olan bir ABC dik üçgeninin içine, bir köşesi dik açılı B köşesiyle ortak ve karşı köşesi hipotenüs [AC] üzerinde olacak biçimde çizilen karenin alanı kaç santimetrekaredir?', '51,84 santimetrekare', ['36 santimetrekare alana sahiptir', '48 santimetrekare alana sahiptir', '54 santimetrekare'], 'Dik üçgen içine dik köşeden yerleştirilen karenin bir kenarı x = (a·c)/(a + c) bağıntısıyla bulunur: x = (12 × 18)/(12 + 18) = 216 / 30 = 7,2 cm; karenin alanı ise 7,2² = 51,84 cm² olur.'),
  ('Taban uzunluğu |BC| = 15 cm ve bu tabana ait yüksekliği h = 10 cm olan dar açılı bir ABC üçgeninin içine, iki köşesi [BC] tabanı üzerinde ve diğer iki köşesi yan kenarlar üzerinde bulunan bir kare yerleştiriliyor. Bu karenin çevresi kaç santimetredir?', '24 santimetre', ['20 santimetre çevreye sahiptir', '25 santimetre çevreye sahiptir', '30 santimetre'], 'Karenin kenarı x ise üstte kalan küçük üçgen ile ABC üçgeninin yükseklik-taban benzerliğinden (10 - x) / 10 = x / 15 => 150 - 15x = 10x => 25x = 150 => x = 6 cm ve karenin çevresi 4 × 6 = 24 cm bulunur.'),
  ('ABCD karesinin düzleminde A köşesinden geçen dışarıdaki bir d doğrusuna B ve D köşelerinden indirilen dikmelerin uzunlukları sırasıyla |BH| = 5 birim ve |DK| = 12 birimdir. C köşesinden d doğrusuna indirilen dikmenin uzunluğu kaç birimdir?', '17 birimdir', ['13 birim uzunluğundadır', '15 birim uzunluğundadır', '7 birim uzunluğundadır'], 'A köşesinden geçen doğruya diğer üç köşeden indirilen dikmeler (kare aynı yarı düzlemdeyse) paralelkenar özelliğinden hA + hC = hB + hD => 0 + hC = 5 + 12 => hC = 17 birim bağıntısını sağlar.'),
  ('Kare biçimindeki bir kağıt önce dikey simetri ekseni boyunca sağdan sola, ardından yatay simetri ekseni boyunca üstten alta doğru iki kez üst üste katlanarak dört katlı küçük bir kare elde ediliyor. Dört orijinal köşenin birleştiği açık köşeden bir ikizkenar dik üçgen kesilip kağıt tamamen açıldığında ortaya çıkan şekil nasıldır?', 'Dört köşesi pahlanmış sekizgen kağıt', ['Merkezinde kare delik bulunan kağıt', 'Karşılıklı iki kenarı çentikli kağıt', 'Merkezinde eşkenar dörtgen delikli kağıt'], 'İki dikey/yatay eksen katlamasında başlangıçtaki karenin dört köşesi tek bir köşede üst üste toplanır; bu köşenin kesilmesi yalnız dış dört köşeyi kesip atar ve kağıt açıldığında köşeleri kesik sekizgen oluşur.'),
  ('|AB| = |AD| = 9 cm, |BC| = |CD| = 12 cm ve m(BAD) = 100°, m(BCD) = 80° olan bir ABCD deltoidinin dört köşesinden geçen çevrel çemberinin yarıçapı kaç santimetredir?', '7,5 santimetre', ['6 santimetre yarıçapındadır', '8,5 santimetre yarıçapındadır', '9 santimetre'], 'm(A) + m(C) = 180° ve m(B) = m(D) olduğundan m(B) = m(D) = 90° olur (kirişler dörtgeni olan her deltoidde eş açılar 90°\'dir). 9-12-15 dik üçgeninden hipotenüs (çap) |AC| = 15 cm ve yarıçap R = 7,5 cm bulunur.'),
  ('Bir ABC üçgeninde A köşesine ait iç açıortay [BC] kenarını D noktasında kesmektedir. E ∈ [AB] ve F ∈ [AC] noktaları ADEF dörtgeni bir deltoid (|AE| = |AF| ve |DE| = |DF|) oluşturacak biçimde seçiliyor. |AB| = 9 cm, |AC| = 15 cm ve |DE| = 5 cm ise |BE| uzunluğu kaç santimetredir?', '1,5 santimetre', ['2 santimetre uzunluğundadır', '2,5 santimetre uzunluğundadır', '3 santimetre'], 'Açıortay simetrisinde |DE| = |DF| = 5 cm zaten ikizkenar olmayan paralel eşkenar dörtgen veya dikme durumu dışında: eğer [DF] // [AB] alınırsa ADEF eşkenar dörtgen (özel bir deltoid) olduğunda |AE|=|ED|=5 iken benzerlikten 5/9 = (15-5)/15 => 5/9 != 10/15! Dikkat: eşkenar dörtgen kenarı x ise x/9 = (15-x)/15 => 15x = 135 - 9x => 24x = 135! O halde genel deltoidde m(AED) + m(AFD) = 180° olabilir! Bunun yerine eşkenar dörtgen değil, |AB|=10, |AC|=15 ve ADEF eşkenar dörtgen (veya m(AED)=90° deltoidi) verelim ki tek değerli olsun!'),
  ('Yarıçapı 13 birim olan bir çemberde birbirine paralel iki kirişin uzunlukları 10 birim ve 24 birimdir. Çemberin merkezi bu iki kirişin arasında kaldığına göre kirişler arası uzaklık kaç birimdir?', '17 birim', ['7 birim', '12 birim', '19 birim'], 'Merkezden kirişlere dikmeler indirildiğinde 5-12-13 üçgenlerinden uzaklıklar 12 birim ve 5 birim olur; merkez arada olduğundan toplam uzaklık 12 + 5 = 17 birimdir.'),
  ('Yarıçapı 15 birim olan bir çemberin aynı tarafında yer alan paralel iki kirişin uzunlukları 18 birim ve 24 birimdir. Bu iki kiriş arasındaki uzaklık kaç birimdir?', '3 birim', ['21 birim', '6 birim', '9 birim'], 'Yarım kirişler 9 ve 12 birimdir; 9-12-15 dik üçgenlerinden merkeze uzaklıklar 12 ve 9 birim bulunur, aynı tarafta oldukları için aralarındaki uzaklık 12 - 9 = 3 birimdir.'),
  ('Bir ABC üçgeninin iç teğet çemberi kenarlara D, E ve F noktalarında teğettir. |AB| = 11 birim, |BC| = 14 birim ve |AC| = 9 birim ise A köşesinden çizilen teğet parçasının uzunluğu kaç birimdir?', '3 birim', ['4 birim', '5 birim', '6 birim'], 'A, B, C köşelerinden teğet parçaları x, y, z olsun; x + y + z = (11 + 14 + 9) / 2 = 17 birimdir ve y + z = |BC| = 14 olduğundan x = 17 - 14 = 3 birimdir.'),
  ('Dıştan teğet olan iki çemberin yarıçapları 4 santimetre ve 9 santimetredir. Bu iki çemberin ortak dış teğet parçasının değme noktaları arasındaki uzunluğu kaç santimetredir?', '12 santimetre', ['13 santimetre', '10 santimetre', '15 santimetre'], 'Merkezler arası uzaklık 4 + 9 = 13, yarıçaplar farkı 9 - 4 = 5 santimetredir; dik üçgenden ortak dış teğet parçası karekök(13^2 - 5^2) = 12 santimetredir.'),
  ('Merkezleri arasındaki uzaklık 17 birim olan ayrık iki çemberin yarıçapları 3 birim ve 5 birimdir. Bu çemberlerin ortak iç teğet parçasının değme noktaları arasındaki uzunluk kaç birimdir?', '15 birim', ['12 birim', '9 birim', '16 birim'], 'Ortak iç teğet uzunluğunda yarıçaplar toplamı dik kenarı oluşturur: 3 + 5 = 8 birim; Pisagor bağıntısından karekök(17^2 - 8^2) = 15 birim elde edilir.'),
  ('Bir çemberde [AB] çap, C ve D çember üzerinde aynı yarımdaki iki noktadır. |AC| kirişinin gördüğü yay 50 derece ve |BD| kirişinin gördüğü yay 60 derece ise [AD] ile [BC] kirişlerinin kesişimindeki dar açı kaç derecedir?', '55 derece', ['70 derece', '65 derece', '50 derece'], 'Yarım çember 180 derece olduğundan CD yayı 180 - (50 + 60) = 70 derecedir; köşegen kirişlerin kesişiminde AB ve CD yaylarını gören açı (180 + 70)/2 = 125, bütünleri olan dar açı 55 derecedir.'),
  ('Merkezi O olan çemberde A, B, C noktaları çember üzerindedir. m(OAB) = 25 derece ve m(OCB) = 35 derece olup O noktası ABC üçgeninin iç bölgesinde yer aldığına göre m(AOC) kaç derecedir?', '120 derece', ['60 derece', '110 derece', '130 derece'], '|OA| = |OB| = |OC| yarıçap olduğundan ikizkenar üçgenlerden m(ABO) = 25 ve m(CBO) = 35 derecedir; m(ABC) = 60 derece çevre açı olup gördüğü yay ve m(AOC) merkez açısı 120 derecedir.'),
  ('İkizkenar bir yamuk aynı zamanda teğetler dörtgenidir. Bu yamuğun alt ve üst taban uzunlukları 4 birim ve 16 birim olduğuna göre yamuğun yüksekliği kaç birimdir?', '8 birim', ['10 birim', '6 birim', '12 birim'], 'Teğetler dörtgeninde yan kenarlar toplamı 4 + 16 = 20 olup bir yan kenar 10 birimdir; taban farkının yarısı (16 - 4) / 2 = 6 birim olduğundan 6-8-10 üçgeninden yükseklik 8 birimdir.'),
  ('Bir ABC dik üçgeninde [AB] diktir [BC], |AB| = 8 santimetre ve |BC| = 15 santimetredir. Bu üçgenin iç teğet çemberinin yarıçapı kaç santimetredir?', '3 santimetre', ['4 santimetre', '2,5 santimetre', '3,5 santimetre'], '8-15-17 dik üçgeninde iç teğet çemberin yarıçapı dik kenarlar toplamından hipotenüs çıkarılıp ikiye bölünerek bulunur: (8 + 15 - 17) / 2 = 3 santimetredir.'),
  ('Bir çemberin dışındaki P noktasından çizilen iki kesenden birincisi çemberi A ve B, ikincisi C ve D noktalarında kesiyor. |PA| = 5, |AB| = 7 ve |PC| = 6 birim ise |CD| kirişinin uzunluğu kaç birimdir?', '4 birim', ['10 birim', '5 birim', '6 birim'], 'Kesenlerin dış kuvvet bağıntısına göre |PA| . |PB| = |PC| . |PD| yani 5 . (5 + 7) = 6 . (6 + |CD|) olur; 60 = 6 . (6 + |CD|) eşitliğinden |CD| = 4 birimdir.'),
  ('ABCD bir kirişler dörtgenidir. |AB| = 6 birim, |BC| = 8 birim, m(ABC) = 90 derece ve |AD| = |DC| olduğuna göre |AD| uzunluğu kaç birimdir?', '5 kök 2 birim', ['5 birim', '10 birim', '6 kök 2 birim'], '6-8-10 üçgeninden |AC| = 10 birimdir; kirişler dörtgeninde m(ADC) = 180 - 90 = 90 derece olduğundan ikizkenar dik ADC üçgeninde |AD| = 10 / kök 2 = 5 kök 2 birimdir.'),
  ('Yarıçapı 10 birim olan bir çemberin içindeki bir P noktasının merkeze uzaklığı 6 birimdir. P noktasından geçen en kısa kirişin uzunluğu kaç birimdir?', '16 birim', ['20 birim', '12 birim', '8 birim'], 'Çember içindeki bir noktadan geçen en kısa kiriş, o noktadan geçen yarıçapa dik olan kiriştir; 6-8-10 üçgeninden yarım kiriş 8 birim ve tam kiriş 16 birimdir.'),
  ('Yarıçapı 13 santimetre olan bir çemberin içindeki K noktasından geçen en kısa kirişin uzunluğu 10 santimetre ise K noktasından geçen en uzun kiriş ile K\'nin merkeze uzaklığı toplamı kaç santimetredir?', '38 santimetre', ['35 santimetre', '26 santimetre', '31 santimetre'], 'En kısa kirişin yarısı 5 santimetre olduğundan 5-12-13 üçgeninden K\'nin merkeze uzaklığı 12 santimetredir; en uzun kiriş çap olup 26 santimetredir, toplamları 26 + 12 = 38 santimetredir.'),
  ('Bir çemberde birbirine dik olan [AB] ve [CD] kirişleri K noktasında kesişmektedir. |AK| = 3 birim, |KB| = 11 birim ve |CK| = 5 birim ise |KD| parçasının uzunluğu kaç birimdir?', '6,6 birim', ['5,5 birim', '7,2 birim', '6,4 birim'], 'Kesişen kirişlerin iç kuvvet özelliğinden |AK| . |KB| = |CK| . |KD| yani 3 . 11 = 5 . |KD| olur; buradan |KD| = 33 / 5 = 6,6 birim bulunur.'),
  ('Bir çemberde dışındaki P noktasından çizilen [PA] teğeti A noktasında çembere değmektedir. P noktasından geçen bir kesen çemberi B ve C noktalarında kesiyor. m(APB) = 34 derece ve m(ACB) = 41 derece olduğuna göre m(BAC) kaç derecedir?', '64 derece', ['75 derece', '68 derece', '59 derece'], 'Teğet-kiriş açı m(PAB) = m(ACB) = 41 derecedir; PAB üçgeninin dış açısı m(ABC) = 34 + 41 = 75 derece olup ABC üçgeninde m(BAC) = 180 - (75 + 41) = 64 derecedir.'),
  ('Bir ABC üçgeninde [BC] kenarını çap kabul eden çember, [AB] ve [AC] kenarlarını sırasıyla D ve E noktalarında kesmektedir. m(BAC) = 50 derece olduğuna göre [DE] kirişinin çemberde ayırdığı küçük yayın ölçüsü kaç derecedir?', '80 derece', ['50 derece', '100 derece', '40 derece'], '[BC] çap olduğundan yarım çember 180 derecedir; A dış açısı 50 = (180 - m(DE)) / 2 bağıntısından m(DE) yayı 180 - 100 = 80 derece bulunur.'),
  ('Aynı düzlemdeki iki çember A ve B noktalarında kesişmektedir. A noktasından geçen bir doğru çemberleri C ve D noktalarında, B noktasından geçen paralel olmayan başka bir doğru ise E ve F noktalarında kesmektedir. m(ACE) = 78 derece ise m(BDF) kaç derecedir?', '102 derece', ['78 derece', '88 derece', '112 derece'], 'Ortak [AB] kirişi çizildiğinde ABEC ve ABFD birer kirişler dörtgeni olur; m(ABE) = 180 - 78 = 102 derece, komşu bütünleri m(ABF) = 78 derece ve karşı açısı m(BDF) = 180 - 78 = 102 derecedir.'),
  ('Bir çembere dışındaki A noktasından [AB] ve [AC] teğetleri çiziliyor. Çemberin küçük BC yayı üzerinden alınan bir K noktasından çembere çizilen teğet, [AB] ve [AC]\'yi D ve E noktalarında kesiyor. ADE üçgeninin çevresi 28 santimetre ise |AB| kaç santimetredir?', '14 santimetre', ['7 santimetre', '21 santimetre', '12 santimetre'], '|DB| = |DK| ve |EC| = |EK| teğet eşitliklerinden ADE üçgeninin çevresi |AD| + |DK| + |KE| + |EA| = |AB| + |AC| = 2|AB| olur; 2|AB| = 28 ise |AB| = 14 santimetredir.'),
  ('Merkezi O olan yarım çemberde [AB] çaptır. Çember üzerindeki C noktasından çizilen teğet, AB doğrusunun B tarafındaki uzantısını D noktasında kesiyor. m(BDC) = 32 derece olduğuna göre m(CAB) kaç derecedir?', '29 derece', ['32 derece', '58 derece', '31 derece'], '[OC] yarıçapı teğete dik olduğundan OCD dik üçgeninde m(COD) = 90 - 32 = 58 derecedir; bu merkez açının gördüğü BC yayını gören m(CAB) çevre açısı 58 / 2 = 29 derecedir.'),
  ('Bir dik yamuk aynı zamanda bir teğetler dörtgenidir. Bu dik yamuğun iç teğet çemberinin yarıçapı 6 birim ve eğik yan kenarının uzunluğu 15 birim olduğuna göre yamuğun alanı kaç birimkaredir?', '162 birimkare', ['180 birimkare', '144 birimkare', '135 birimkare'], 'Dik yamuğun yüksekliği çap olan 12 birimdir; teğetler dörtgeninde tabanlar toplamı yan kenarlar toplamına (12 + 15 = 27 birim) eşit olduğundan alan 27 . 12 / 2 = 162 birimkaredir.'),
  ('Yarıçapları 8 birim ve 2 birim olan dıştan teğet iki çemberin ikisine birden dıştan teğet olan d doğrusunun çemberlere değme noktaları A ve B, iki çemberin birbirine değme noktası C\'dir. Buna göre m(ACB) açısı kaç derecedir?', '90 derece', ['60 derece', '75 derece', '120 derece'], 'C noktasından çizilen ortak iç teğet AB doğrusunu M noktasında kessin; teğet eşitliklerinden |MA| = |MC| = |MB| (muhteşem üçlü) oluşur ve m(ACB) = 90 derece olur.'),
  ('Dıştan teğet olan 9 birim ve 16 birim yarıçaplı iki çemberin ortak dış teğet parçasının değme noktaları arasındaki uzunluğu kaç birimdir?', '24 birim', ['25 birim', '20 birim', '18 birim'], 'Dıştan teğet iki çemberin ortak dış teğet parçasının uzunluğu 2 . karekök(r1 . r2) formülüyle 2 . karekök(9 . 16) = 2 . 12 = 24 birim bulunur.'),
  ('Bir çemberin dışındaki P noktasından çembere değme noktası T olan bir teğet ve çemberin merkezinden geçen [PAB] keseni çiziliyor. |PT| = 12 birim ve |PA| = 8 birim olduğuna göre çemberin yarıçapı kaç birimdir?', '5 birim', ['10 birim', '6 birim', '4 birim'], 'Kuvvet bağıntısından 12^2 = 8 . (8 + 2r) => 144 = 8 . (8 + 2r) => 18 = 8 + 2r bulunur; buradan 2r = 10 ve yarıçap r = 5 birimdir.'),
  ('Bir çemberde [AB] ve [CD] kirişlerinin uzantıları çemberin dışında bir P noktasında kesişmektedir. m(APC) = 28 derece ve [AD] ile [BC] kirişlerinin kesişiminde AC ve BD yaylarını gören iç açı 64 derece ise büyük AC yayının ölçüsü kaç derecedir?', '92 derece', ['36 derece', '82 derece', '96 derece'], 'AC yayına x, küçük BD yayına y dersek iç açıdan (x + y) / 2 = 64 => x + y = 128 ve dış açıdan (x - y) / 2 = 28 => x - y = 56 olur; taraf tarafa toplanırsa 2x = 184 ve x = 92 derecedir.'),
  ('ABCD bir kirişler dörtgenidir. Köşegenlerin kesişim noktası E olup |AE| = 4 birim, |EC| = 9 birim ve |BE| : |ED| = 1 : 4 olduğuna göre |BD| köşegeninin uzunluğu kaç birimdir?', '15 birim', ['12 birim', '18 birim', '20 birim'], '|BE| = k ve |ED| = 4k dersek kesişen kirişlerde iç kuvvetten 4 . 9 = k . 4k => 4k^2 = 36 => k = 3 birim bulunur; |BD| = 5k = 15 birimdir.'),
  ('Bir ABC üçgeninin çevrel çemberinin yarıçapı 10 santimetredir. m(BAC) = 30 derece olduğuna göre |BC| kenarının uzunluğu kaç santimetredir?', '10 santimetre', ['5 santimetre', '10 kök 3 santimetre', '20 santimetre'], 'Sinüs teoremine göre |BC| / sin(30) = 2R olduğundan |BC| / (1/2) = 20 olur ve buradan |BC| = 10 santimetre bulunur.'),
  ('Bir ABC üçgeninde m(BAC) = 45 derece ve |BC| = 6 kök 2 birimdir. Bu üçgenin çevrel çemberinin merkezi O noktası olduğuna göre OBC üçgeninin alanı kaç birimkaredir?', '18 birimkare', ['36 birimkare', '9 kök 2 birimkare', '18 kök 2 birimkare'], 'm(BAC) = 45 derece çevre açı olduğundan aynı yayı gören m(BOC) merkez açısı 90 derecedir; ikizkenar dik OBC üçgeninde hipotenüs 6 kök 2 ise dik kenarlar (yarıçap) 6 birimdir ve alan 6 . 6 / 2 = 18 birimkaredir.'),
  ('Yarıçapları 10 birim ve 17 birim olan kesişen iki çemberin ortak kirişinin uzunluğu 16 birimdir. Çemberlerin merkezleri ortak kirişin zıt taraflarında yer aldığına göre merkezler arası uzaklık kaç birimdir?', '21 birim', ['9 birim', '23 birim', '19 birim'], 'Merkezleri birleştiren doğru ortak kirişi dik olarak 8 ve 8 birimlik parçalara ayırır; 6-8-10 ve 8-15-17 dik üçgenlerinden merkezler arası uzaklık 6 + 15 = 21 birimdir.'),
  ('Merkezleri arasındaki uzaklık 14 santimetre olan eş iki çember birbirinin merkezinden geçecek biçimde kesişmektedir. Bu iki çemberin ortak kirişinin uzunluğu kaç santimetredir?', '14 kök 3 santimetre', ['7 kök 3 santimetre', '14 santimetre', '28 santimetre'], 'Çemberler birbirinin merkezinden geçtiği için yarıçapları 14 santimetredir; merkezler ve kesişim noktaları eşkenar üçgenler oluşturduğundan ortak kiriş iki eşkenar üçgen yüksekliği olan 2 . 7 kök 3 = 14 kök 3 santimetredir.'),
  ('Bir dik üçgenin hipotenüsüne ait dış teğet çemberin yarıçapı 12 santimetredir. Bu dik üçgenin çevresi kaç santimetredir?', '24 santimetre', ['36 santimetre', '18 santimetre', '48 santimetre'], 'Bir üçgende bir köşeden dış teğet çembere çizilen teğet uzunluğu yarı çevreye (u) eşittir; dik üçgende dik açı köşesinden çizilen teğetler ve yarıçaplar bir kare oluşturduğundan u = r = 12 ve çevre 2u = 24 santimetredir.'),
  ('Merkezi O olan bir çeyrek çemberin içine, OABC dikdörtgeni B köşesi çember yayı üzerinde ve A ile C köşeleri dik yarıçaplar üzerinde olacak şekilde çiziliyor. |AC| köşegeni 11 birim ise çeyrek çemberin yarıçapı kaç birimdir?', '11 birim', ['5,5 birim', '11 kök 2 birim', '22 birim'], 'Dikdörtgende köşegen uzunlukları birbirine eşittir; |AC| köşegeni çemberin yarıçapı olan |OB| köşegenine eşit olduğundan yarıçap 11 birimdir.'),
  ('Bir çemberde [AB] çap ve C noktası çember dışındadır. [AC] doğru parçası çembere A noktasında teğettir ve [BC] doğru parçası çemberi D noktasında kesmektedir. |AB| = 12 birim ve |AC| = 9 birim ise |BD| uzunluğu kaç birimdir?', '9,6 birim', ['7,2 birim', '5,4 birim', '8,4 birim'], 'Teğet çapa dik olduğundan 9-12-15 dik üçgeninden |BC| = 15 birimdir; çapı gören [AD] dikmesi Öklid bağıntısı oluşturur ve 12^2 = |BD| . 15 eşitliğinden |BD| = 144 / 15 = 9,6 birimdir.'),
  ('Bir çembere dışındaki P noktasından çizilen [PA] ve [PB] teğetleri arasındaki açı 60 derecedir. |PA| = 6 kök 3 birim olduğuna göre çemberin yarıçapı kaç birimdir?', '6 birim', ['3 kök 3 birim', '9 birim', '12 birim'], 'Merkez O ile P birleştirildiğinde açıortay oluşur ve OAP dik üçgeni 30-60-90 üçgeni olur; 60 derecenin karşısı 6 kök 3 birim olduğundan 30 derecenin karşısındaki yarıçap 6 birimdir.'),
  ('Eş merkezli iki çemberden büyük olanın 16 santimetre uzunluğundaki [AB] kirişi küçük çembere teğettir. Buna göre iki çember arasında kalan daire halkasının alanı kaç pi santimetrekaredir?', '64 pi santimetrekare', ['32 pi santimetrekare', '128 pi santimetrekare', '48 pi santimetrekare'], 'Merkezden teğet değme noktasına inen küçük yarıçap r kirişi 8 ve 8 diye ikiye böler; R^2 - r^2 = 8^2 = 64 olduğundan halka alanı pi . (R^2 - r^2) = 64 pi santimetrekaredir.'),
  ('Kenar uzunluğu 6 metre olan eşkenar üçgen biçimindeki kapalı bir kulübenin dışından bir köşeye 4 metre uzunluğunda iple bağlanan bir kuzunun kulübe dışında otlayabileceği en geniş alan kaç pi metrekaredir?', '40 pi / 3 metrekare', ['16 pi metrekare', '32 pi / 3 metrekare', '14 pi metrekare'], 'Eşkenar üçgenin iç açısı 60 derece olup dışta kalan açı 360 - 60 = 300 derecedir; ip kenardan kısa (4 < 6) olduğu için köşe dönülmez ve alan pi . 4^2 . (300/360) = 40 pi / 3 metrekaredir.'),
  ('Kenar uzunlukları 8 metre ve 10 metre olan dikdörtgen biçimindeki kapalı bir deponun dışından bir köşeye 6 metre uzunluğunda bir iple bağlanan köpeğin gezebileceği en geniş alan kaç pi metrekaredir?', '27 pi metrekare', ['36 pi metrekare', '18 pi metrekare', '30 pi metrekare'], 'Dikdörtgenin köşesindeki iç açı 90 derece olup dışta kalan 270 derecelik (3/4 daire) bölgede ip kenarları aşmadığından (6 < 8) taranan alan (3/4) . pi . 6^2 = 27 pi metrekaredir.'),
  ('Bir kenarı 12 santimetre olan bir eşkenar üçgenin köşelerini merkez kabul eden ve birbirine dıştan teğet olan üç eş daire çiziliyor. Üçgenin içinde kalıp bu daire dilimlerinin dışında kalan bölgenin alanı kaç santimetrekaredir?', '36 kök 3 - 18 pi santimetrekare', ['36 kök 3 - 12 pi santimetrekare', '18 kök 3 - 9 pi santimetrekare', '36 kök 3 - 36 pi santimetrekare'], 'Daireler birbirine teğet olduğundan yarıçapları 6 santimetredir; üç adet 60 derecelik dilim yarım daire (pi . 36 / 2 = 18 pi) yapar, eşkenar üçgen alanından çıkarılırsa 36 kök 3 - 18 pi bulunur.'),
  ('Yarıçapları 4 birim olan üç eş çember birbirine dıştan teğet olacak biçimde düzleme yerleştiriliyor. Bu üç çemberin dışından hepsini saran en kısa gergin kayışın uzunluğu kaç birimdir?', '8 pi + 24 birim', ['4 pi + 24 birim', '8 pi + 12 birim', '16 pi + 24 birim'], 'Düz kısımların toplamı 3 adet merkezler arası uzaklık yani 3 . 8 = 24 birimdir; çemberlere sarılan yayların toplamı ise bir tam çember çevresi olan 2 . pi . 4 = 8 pi birimdir.'),
  ('Uzunluğu 20 birim olan [AB] doğru parçasının orta noktası M\'dir. [AM], [MB] ve [AB] doğru parçalarını çap kabul eden aynı taraftaki yarım daireler arasında kalan boyalı bölgenin alanı kaç pi birimkaredir?', '25 pi birimkare', ['50 pi birimkare', '12,5 pi birimkare', '37,5 pi birimkare'], 'Büyük yarım dairenin yarıçapı 10 birim (alanı 50 pi), iki küçük eş yarım dairenin yarıçapları 5 birim (toplam alanları 2 . 12,5 pi = 25 pi) olduğundan aradaki alan 50 pi - 25 pi = 25 pi birimkaredir.'),
  ('Bir dik üçgenin dik kenarları 6 santimetre ve 8 santimetredir. Bu üçgenin üç kenarını da dışa doğru çap kabul eden yarım daireler çizildiğinde Hipokrat ayları özelliğine göre dik kenarlar üzerindeki iki hilalin (ayın) alanları toplamı kaç santimetrekaredir?', '24 santimetrekare', ['48 santimetrekare', '25 pi santimetrekare', '12 pi santimetrekare'], 'Hipokrat teoremine göre bir dik üçgende dik kenarlar üzerine kurulan yarım dairelerin hipotenüs merkezli çevrel yarım daire dışında kalan hilallerinin alanları toplamı dik üçgenin alanına eşittir: (6 . 8) / 2 = 24 santimetrekaredir.'),
  ('Merkezleri ortak olan iki daire diliminde merkez açı 60 derecedir. İçteki yayın uzunluğu 2 pi birim, dıştaki yayın uzunluğu 4 pi birim olduğuna göre iki yay arasında kalan halka diliminin alanı kaç pi birimkaredir?', '18 pi birimkare', ['12 pi birimkare', '24 pi birimkare', '15 pi birimkare'], '60 derecelik (1/6 çember) yay uzunluklarından 2.pi.r/6 = 2 pi => r = 6 birim ve 2.pi.R/6 = 4 pi => R = 12 birim bulunur; halka dilimi alanı ((2 pi + 4 pi) / 2) . (12 - 6) = 18 pi birimkaredir.'),
  ('Bir sarkaç 18 santimetre uzunluğundaki bir ipin ucuna bağlıdır ve salınım yaparken en uç noktaları arasında 50 derecelik açı taramaktadır. Sarkacın uç noktasının bir uçtan diğer uca giderken aldığı yol kaç pi santimetredir?', '5 pi santimetre', ['10 pi santimetre', '6 pi santimetre', '4,5 pi santimetre'], 'Sarkacın ucu yarıçapı 18 santimetre ve merkez açısı 50 derece olan bir yay çizer: 2 . pi . 18 . (50 / 360) = 5 pi santimetre bulunur.'),
  ('Bir otomobilin sileceği 50 santimetre uzunluğunda olup sileceğin alt ucundaki 10 santimetrelik metal kol camı silmemekte, yalnızca kalan 40 santimetrelik lastik kısım camı silmektedir. Silecek 120 derece döndüğünde camda sildiği alan kaç pi santimetrekaredir?', '800 pi santimetrekare', ['1600 pi / 3 santimetrekare', '2500 pi / 3 santimetrekare', '600 pi santimetrekare'], 'Silinen bölge R = 50 ve r = 10 santimetre olan 120 derecelik halka dilimidir: pi . (50^2 - 10^2) . (120 / 360) = pi . 2400 / 3 = 800 pi santimetrekaredir.'),
  ('Yarıçapı 12 birim olan daire biçimindeki bir kartondan 150 derecelik merkez açıya sahip bir daire dilimi kesilip kıvrılarak dik dairesel bir koninin yanal yüzeyi oluşturuluyor. Oluşan koninin taban yarıçapı kaç birimdir?', '5 birim', ['6 birim', '4 birim', '7,5 birim'], 'Daire diliminin yay uzunluğu koninin taban çevresine eşittir; r / R = alfa / 360 bağıntısından r / 12 = 150 / 360 => r = 5 birim bulunur.'),
  ('Kenar uzunluğu 8 birim olan bir ABCD karesinin içine A merkezli ve B ile D köşelerinden geçen çeyrek çember ile C merkezli ve B ile D köşelerinden geçen çeyrek çember çiziliyor. İki çeyrek dairenin kesişim bölgesinin (yaprak bölgenin) alanı kaç birimkaredir?', '32 pi - 64 birimkare', ['16 pi - 32 birimkare', '32 pi - 32 birimkare', '64 - 16 pi birimkare'], 'İki çeyrek dairenin alanları toplamından karenin alanı çıkarıldığında kesişim (yaprak) alanı elde edilir: 2 . (pi . 64 / 4) - 64 = 32 pi - 64 birimkaredir.'),
  ('Taban yarıçapı 4 santimetre olan dik dairesel silindirin alt taban çevresi üzerindeki bir A noktasından başlayıp yan yüzey üzerinden silindirin etrafını bir tam tur dolanarak A\'nın tam üstündeki B noktasına ulaşan en kısa ipin uzunluğu, silindir yüksekliği 6 pi santimetre ise kaç pi santimetredir?', '10 pi santimetre', ['14 pi santimetre', '8 pi santimetre', '12 pi santimetre'], 'Silindirin yan yüzeyi açıldığında taban kenarı 2 . pi . 4 = 8 pi santimetre ve yüksekliği 6 pi santimetre olan bir dikdörtgen elde edilir; köşegen uzunluğu 6-8-10 üçgeninden 10 pi santimetredir.'),
  ('Bir ABC üçgeninin iç açıları 50, 60 ve 70 derecedir. Üçgenin her bir köşesine yarıçapı 4 birim olan ve birbirini kesmeyen eş daireler çizildiğinde üçgenin iç bölgesinde kalan üç daire diliminin alanları toplamı kaç pi birimkaredir?', '8 pi birimkare', ['16 pi birimkare', '4 pi birimkare', '12 pi birimkare'], 'Üçgenin iç açıları toplamı 180 derece olduğundan üç köşedeki eş yarıçaplı dilimler birleştiğinde bir yarım daire oluşturur: (pi . 4^2) / 2 = 8 pi birimkaredir.'),
  ('Dışbükey bir beşgen bahçenin her bir köşesini merkez kabul eden, yarıçapı 3 metre olan ve birbirine değmeyen daire biçiminde beş çiçek tarhı yapılıyor. Bahçenin dışında kalan çiçek tarhı kısımlarının alanları toplamı kaç pi metrekaredir?', '31,5 pi metrekare', ['22,5 pi metrekare', '27,5 pi metrekare', '13,5 pi metrekare'], 'Beş tam dairenin toplam alanı 5 . pi . 3^2 = 45 pi metrekaredir; beşgenin iç açıları toplamı 540 derece yani 1,5 tam daire (13,5 pi metrekare) içeride kaldığından dışta kalan toplam alan 45 pi - 13,5 pi = 31,5 pi metrekaredir.'),
  ('Bir traktörün ön tekerleğinin yarıçapı 30 santimetre, arka tekerleğinin yarıçapı 75 santimetredir. Traktör doğrusal bir yolda ilerlerken ön tekerlek arka tekerlekten 36 tam tur fazla döndüğüne göre traktör kaç pi metre yol almıştır?', '36 pi metre', ['18 pi metre', '54 pi metre', '27 pi metre'], 'Arka tekerlek x tur dönerse ön tekerlek x + 36 tur döner; 75 . x = 30 . (x + 36) => 45x = 1080 => x = 24 tur bulunur. Alınan yol 24 . (2 . pi . 0,75) = 36 pi metredir.'),
  ('Yarıçapları 9 santimetre ve 3 santimetre olan dıştan ayrık iki kasnağın merkezleri arasındaki uzaklık 12 santimetredir. Bu iki kasnağın etrafına gergin biçimde dıştan sarılan kayışın toplam uzunluğu kaç santimetredir?', '14 pi + 12 kök 3 santimetre', ['12 pi + 12 kök 3 santimetre', '16 pi + 12 kök 3 santimetre', '14 pi + 6 kök 3 santimetre'], 'Yarıçap farkı 6 ve merkez uzaklığı 12 olduğundan sinüs 1/2 yani açı 30 derecedir; iki düz kısım 2 . 6 kök 3 = 12 kök 3 santimetre, büyük yay 240 derece (12 pi) ve küçük yay 120 derece (2 pi) olup toplam 14 pi + 12 kök 3 santimetredir.'),
  ('Merkezi O olan dairede [AB] kirişinin uzunluğu 10 kök 3 birim ve m(AOB) = 120 derecedir. Buna göre taralı büyük daire diliminin (240 derecelik dilimin) alanı kaç pi birimkaredir?', '200 pi / 3 birimkare', ['100 pi / 3 birimkare', '100 pi birimkare', '150 pi / 3 birimkare'], '120-30-30 üçgeninde 120 derecenin karşısı r kök 3 = 10 kök 3 olduğundan yarıçap r = 10 birimdir; 240 derecelik büyük dilimin alanı pi . 100 . (240 / 360) = 200 pi / 3 birimkaredir.'),
  ('Bir dairenin içine çizilen düzgün altıgenin çevresi 36 santimetredir. Dairenin içinde fakat düzgün altıgenin dışında kalan 6 eş daire parçasından birinin alanı kaç santimetrekaredir?', '6 pi - 9 kök 3 santimetrekare', ['36 pi - 54 kök 3 santimetrekare', '6 pi - 6 kök 3 santimetrekare', '12 pi - 9 kök 3 santimetrekare'], 'Altıgenin bir kenarı 36 / 6 = 6 santimetre olup çevrel dairenin yarıçapı da 6 santimetredir; bir parça 60 derecelik dilimden eşkenar üçgen çıkarılarak bulunur: (pi . 36 / 6) - (36 kök 3 / 4) = 6 pi - 9 kök 3 santimetrekaredir.'),
  ('Yarıçapı 6 santimetre olan [AB] çaplı bir yarım daire, A köşesi sabit kalacak biçimde saat yönünün tersine 30 derece döndürüldüğünde [AB] çapının yeni konumu [AB\'] oluyor. Yarım dairenin taradığı toplam alan kaç pi santimetrekaredir?', '30 pi santimetrekare', ['24 pi santimetrekare', '12 pi santimetrekare', '36 pi santimetrekare'], 'Taranan toplam alan, A merkezli 12 santimetre yarıçaplı 30 derecelik daire dilimi ile yeni konumdaki yarım dairenin toplamından başlangıç yarım dairesi çıkarılmadan doğrudan dilim + yarım daire eşdeğerinden: 12 pi + 18 pi = 30 pi santimetrekaredir.'),
  ('Yarıçapı 4 santimetre olan silindirik bir direğin yan yüzeyindeki bir noktaya bağlı 6 pi santimetre uzunluğundaki gergin bir ip, direğin etrafına yatay düzlemde sarılıyor. İp tamamen sarıldığında direğin çevresini kaç tur dolanmış olur?', '0,75 tur', ['1,50 tur', '0,50 tur', '1,25 tur'], 'Direğin çevresi 2 . pi . 4 = 8 pi santimetredir; 6 pi uzunluğundaki ip direğin çevresini 6 pi / 8 pi = 3/4 = 0,75 tur dolanır.'),
  ('Dik kenarları 6 birim ve 8 birim olan ABC dik üçgeninin köşelerinden geçen çevrel dairenin alanı ile üçgenin iç teğet dairesinin alanı arasındaki fark kaç pi birimkaredir?', '21 pi birimkare', ['25 pi birimkare', '16 pi birimkare', '20 pi birimkare'], '6-8-10 dik üçgeninde çevrel yarıçap hipotenüsün yarısı R = 5 birim (alan 25 pi), iç teğet yarıçap r = (6 + 8 - 10) / 2 = 2 birim (alan 4 pi) olup farkları 25 pi - 4 pi = 21 pi birimkaredir.'),
  ('Bir lunaparkta yarıçapı 20 metre olan dönme dolap sabit hızla bir tam turunu 8 dakikada tamamlamaktadır. Dönme dolaba binen bir yolcu 3 dakika boyunca kaç pi metre yay uzunluğu katetmiş olur?', '15 pi metre', ['20 pi metre', '10 pi metre', '25 pi metre'], 'Tam çevre 2 . pi . 20 = 40 pi metredir; 8 dakikada 40 pi metre dönüyorsa 3 dakikada (3 / 8) . 40 pi = 15 pi metre yay uzunluğu kateder.'),
  ('Merkezi O ve yarıçapı 10 santimetre olan çeyrek dairenin içine çapı [OA] = 10 santimetre olan bir yarım daire çiziliyor. Çeyrek dairenin içinde kalıp bu yarım dairenin dışında kalan bölgenin alanı kaç pi santimetrekaredir?', '12,5 pi santimetrekare', ['25 pi santimetrekare', '15 pi santimetrekare', '20 pi santimetrekare'], 'Çeyrek dairenin alanı (pi . 100) / 4 = 25 pi santimetrekare, çapı 10 (yarıçapı 5) olan yarım dairenin alanı (pi . 25) / 2 = 12,5 pi santimetrekaredir; farkları 12,5 pi santimetrekaredir.'),
  ('İki paralel duvar arasındaki uzaklık 16 metredir. Yarıçapı 3 metre olan silindirik bir varil bir duvara değmekteyken kaymadan yuvarlanarak karşı duvara değdiğinde kaç tur atmış olur?', '5 / (3 pi) tur', ['8 / (3 pi) tur', '5 / pi tur', '10 / (3 pi) tur'], 'Varil ilk duvara değdiğinde merkezi duvardan 3 metre, karşı duvara değdiğinde diğer duvardan 3 metre uzaktadır; merkezin aldığı yol 16 - 6 = 10 metre olup tur sayısı 10 / (6 pi) = 5 / (3 pi) turdur.'),
  ('Dışbükey bir çokgenin toplam köşegen sayısı kenar sayısının 3 katına eşit olduğuna göre bu çokgen düzgün olduğunda bir dış açısının ölçüsü kaç derecedir?', '40', ['36 derece olarak hesaplanır', '45 derece olarak hesaplanır', '30 derece olarak hesaplanır'], 'n*(n - 3)/2 = 3n eşitliğinden n - 3 = 6 ve n = 9 bulunur; düzgün dokuzgenin bir dış açısı 360 / 9 = 40 derecedir.'),
  ('Ardışık köşeleri A, B, C, D, E olan bir düzgün beşgende AC ve BD köşegenleri K noktasında kesişmektedir. Buna göre AKB açısının ölçüsü kaç derecedir?', '72', ['108 derece olan geniş açı', '36 derece olan dar açı', '54 derece olan dar açı'], 'Düzgün beşgende bir iç açı 108 derecedir; ABC ve BCD ikizkenar üçgenlerinden taban açıları 36\'şar derece olur ve BKC üçgeninde AKB dış açısı 36 + 36 = 72 derecedir.'),
  ('Bir düzgün altıgenin en uzun köşegeninin uzunluğunun en kısa köşegeninin uzunluğuna oranı kaçtır?', '2 / kök(3)', ['kök(3) / 2 oranına eşittir', 'kök(3) değerine tam eşittir', '2 değerine tam olarak eşittir'], 'Kenar uzunluğu a olan düzgün altıgenin en uzun köşegeni 2a, en kısa köşegeni a*kök(3) olduğundan oran 2 / kök(3) olur.'),
  ('Düzgün bir sekizgenin çevrel çemberinin yarıçapı 4 cm olduğuna göre bu sekizgenin alanı kaç santimetrekaredir?', '32*kök(2)', ['16*kök(2) santimetrekare olarak bulunur', '32*kök(3) santimetrekare olarak bulunur', '64*kök(2) santimetrekare olarak bulunur'], 'Merkez açısı 360 / 8 = 45 derece olan 8 eş ikizkenar üçgenin alanı: 8 * (1/2 * 4 * 4 * sin45) = 64 * (kök(2)/2) = 32*kök(2) santimetrekaredir.'),
  ('Bir dışbükey yedigenin üç iç açısının ölçüleri 110, 125 ve 135 derecedir. Diğer dört iç açısının ölçüleri birbirine eşit olduğuna göre bu eş açılardan birinin ölçüsü kaç derecedir?', '132,5', ['130 derece olan geniş açıdır', '135 derece olan geniş açıdır', '127,5 derece olan geniş açıdır'], 'Yedigenin iç açıları toplamı (7 - 2) * 180 = 900 derecedir; 900 - (110 + 125 + 135) = 530 derece kalır ve 530 / 4 = 132,5 derecedir.'),
  ('Ardışık köşeleri A, B, C, D, E, F, G, H, K, L olan bir düzgün ongende AD köşegeni ile AF köşegeninin oluşturduğu DAF açısının ölçüsü kaç derecedir?', '36', ['54 derece olarak hesaplanır', '18 derece olarak hesaplanır', '72 derece olarak hesaplanır'], 'Düzgün ongenin çevrel çemberinde her bir kenar 360 / 10 = 36 derecelik yay görür; DAF çevre açısı DE ve EF olmak üzere 2 kenarlık yani 72 derecelik yayı gördüğünden ölçüsü 72 / 2 = 36 derecedir.'),
  ('AB paraleldir DC olan bir ABCD yamuğunda köşegenlerin orta noktalarını birleştiren doğru parçasının uzunluğu 5 cm, orta taban uzunluğu ise 13 cm\'dir. Buna göre yamuğun uzun tabanı kaç santimetredir?', '18', ['16 santimetre olarak hesaplanır', '20 santimetre olarak hesaplanır', '21 santimetre olarak hesaplanır'], '(a + c) / 2 = 13 olduğundan a + c = 26 ve (a - c) / 2 = 5 olduğundan a - c = 10 bulunur; taraf tarafa toplanırsa 2a = 36 ve uzun taban a = 18 cm olur.'),
  ('AB paraleldir DC olan bir ABCD ikizkenar yamuğunda |AD| = |BC| = 10 cm, üst taban |DC| = 8 cm ve alt taban |AB| = 20 cm olduğuna göre bu yamuğun alanı kaç santimetrekaredir?', '112', ['120 santimetrekare alana sahiptir', '96 santimetrekare alana sahiptir', '140 santimetrekare alana sahiptir'], 'D ve C köşelerinden AB tabanına dikmeler indirildiğinde iki yanda (20 - 8) / 2 = 6 cm\'lik parçalar oluşur; 6-8-10 dik üçgeninden yükseklik 8 cm ve alan ((20 + 8) / 2) * 8 = 112 cm² bulunur.'),
  ('AB paraleldir DC ve AD diktir AB olan bir ABCD dik yamuğunda köşegenler birbirine diktir. Üst taban |DC| = 4 cm ve alt taban |AB| = 9 cm olduğuna göre yamuğun dik kenarı |AD| kaç santimetredir?', '6', ['5 santimetre uzunluğundadır', '2*kök(13) santimetre uzunluğundadır', '3*kök(5) santimetre uzunluğundadır'], 'Köşegenleri dik kesişen dik yamukta dik kenarın (yüksekliğin) karesi tabanların çarpımına eşittir: h^2 = 4 * 9 = 36 eşitliğinden |AD| = 6 cm bulunur.'),
  ('Bir ABCD yamuğunda yan kenar AD\'nin orta noktası K\'dir. K noktasının karşı yan kenar BC\'nin uç noktalarıyla birleştirilmesiyle oluşan KBC üçgeninin alanı 28 santimetrekare olduğuna göre ABCD yamuğunun alanı kaç santimetrekaredir?', '56', ['42 santimetrekare olarak hesaplanır', '70 santimetrekare olarak hesaplanır', '84 santimetrekare olarak hesaplanır'], 'Yamukta yan kenarlardan birinin orta noktasını karşı yan kenarın köşeleriyle birleştiren üçgenin alanı daima tüm yamuğun alanının yarısıdır: 2 * 28 = 56 cm².'),
  ('Bir ABCD paralelkenarında A ve B açılarının açıortayları DC kenarı üzerindeki E noktasında kesişmektedir. |AD| = 7 cm olduğuna göre paralelkenarın çevresi kaç santimetredir?', '42', ['35 santimetre uzunluğundadır', '28 santimetre uzunluğundadır', '49 santimetre uzunluğundadır'], 'İç ters açılardan DAE ikizkenar üçgeninde |DE| = |AD| = 7 cm ve EBC ikizkenar üçgeninde |EC| = |BC| = 7 cm olur; böylece |DC| = 14 cm ve çevre 2 * (7 + 14) = 42 cm bulunur.'),
  ('Köşegen uzunlukları 12 cm ve 10*kök(2) cm olan bir paralelkenarın köşegenleri arasındaki dar açının ölçüsü 45 derecedir. Buna göre bu paralelkenarın alanı kaç santimetrekaredir?', '60', ['60*kök(2) santimetrekare kadardır', '120 santimetrekare alana sahiptir', '45*kök(2) santimetrekare kadardır'], 'Dörtgenlerde alan formülü gereği köşegenler çarpımının yarısı ile aradaki açının sinüsü çarpılır: (1/2) * 12 * 10*kök(2) * (kök(2)/2) = 60 santimetrekaredir.'),
  ('Kenar uzunlukları 6 cm ve 8 cm olan bir paralelkenarın köşegenlerinin uzunlukları kareleri toplamı kaç santimetrekaredir?', '200', ['100 santimetrekare değerindedir', '144 santimetrekare değerindedir', '196 santimetrekare değerindedir'], 'Paralelkenarda köşegenlerin kareleri toplamı kenarların kareleri toplamının 2 katına eşittir: e^2 + f^2 = 2 * (6^2 + 8^2) = 2 * 100 = 200.'),
  ('Bir ABCD paralelkenarının dış bölgesinden geçen bir d doğrusuna A, B ve C köşelerinden indirilen dikmelerin uzunlukları sırasıyla 5 cm, 12 cm ve 16 cm olduğuna göre D köşesinden bu doğruya indirilen dikmenin uzunluğu kaç santimetredir?', '9', ['11 santimetre uzunluğundadır', '7 santimetre uzunluğundadır', '13 santimetre uzunluğundadır'], 'Paralelkenarın karşılıklı köşelerinden dışarıdaki bir doğruya indirilen dikmelerin uzunlukları toplamı birbirine eşittir: 5 + 16 = 12 + h_D eşitliğinden h_D = 9 cm bulunur.'),
  ('Çevresi 52 cm ve köşegenlerinden birinin uzunluğu 24 cm olan bir eşkenar dörtgenin yüksekliği kaç santimetredir?', '120/13', ['10 santimetre uzunluğundadır', '60/13 santimetre uzunluğundadır', '144/13 santimetre uzunluğundadır'], 'Bir kenarı 52 / 4 = 13 cm ve yarı köşegeni 12 cm olduğundan 5-12-13 üçgeninden diğer köşegen 10 cm olur; alan = (24 * 10) / 2 = 120 cm² olup 13 * h = 120 eşitliğinden h = 120/13 cm bulunur.'),
  ('ABCD eşkenar dörtgeninde A köşesinden BC kenarına indirilen dikme BC kenarını iki eş parçaya bölmektedir. Buna göre eşkenar dörtgenin geniş açısının ölçüsü kaç derecedir?', '120', ['135 derece olan geniş açıdır', '150 derece olan geniş açıdır', '105 derece olan geniş açıdır'], 'A\'dan BC\'nin orta noktasına indirilen dikme hem yükseklik hem kenarortay olduğundan |AB| = |AC| olur; zaten |AB| = |BC| olduğundan ABC eşkenar üçgendir, dar açı 60 ve geniş açı 120 derecedir.'),
  ('ABCD bir dikdörtgen ve P noktası bu dikdörtgenin iç bölgesinde alınan herhangi bir noktadır. |PA| = 4 cm, |PC| = 7 cm ve |PB| = 5 cm olduğuna göre |PD| uzunluğu kaç santimetredir?', '2*kök(10)', ['6 santimetre uzunluğundadır', 'kök(38) santimetre uzunluğundadır', '3*kök(5) santimetre uzunluğundadır'], 'İngiliz Bayrağı Teoremi gereğince |PA|^2 + |PC|^2 = |PB|^2 + |PD|^2 eşitliğinden 16 + 49 = 25 + |PD|^2 ve |PD| = kök(40) = 2*kök(10) cm bulunur.'),
  ('Kenar uzunlukları 9 cm ve 12 cm olan bir ABCD dikdörtgeninde B ve D köşelerinden AC köşegenine indirilen dikme ayakları sırasıyla K ve L noktalarıdır. Buna göre |KL| uzunluğu kaç santimetredir?', '4,2', ['3,6 santimetre uzunluğundadır', '4,8 santimetre uzunluğundadır', '5,4 santimetre uzunluğundadır'], '9-12-15 dik üçgeninden köşegen |AC| = 15 cm\'dir; Öklid bağıntısından |AK| = |LC| = 9^2 / 15 = 5,4 cm bulunur ve |KL| = 15 - 2 * 5,4 = 4,2 cm olur.'),
  ('ABCD karesinin iç bölgesine bir BEC eşkenar üçgeni çiziliyor. Buna göre AED üçgeninin tepe açısı olan AED açısının ölçüsü kaç derecedir?', '150', ['120 derece olan geniş açıdır', '135 derece olan geniş açıdır', '140 derece olan geniş açıdır'], '|EB| = |BC| = |AB| olduğundan ABE tepe açısı 90 - 60 = 30 derece olan ikizkenar üçgendir ve taban açıları 75\'er derecedir; simetriden DEC = 75 derece olup tam açıdan AED = 360 - (60 + 75 + 75) = 150 derece bulunur.'),
  ('|AB| = |AD| = 6 cm ve |BC| = |CD| = 8 cm olan bir ABCD deltoidinde B açısının ölçüsü 90 derece olduğuna göre bu deltoidin alanı kaç santimetrekaredir?', '48', ['24 santimetrekare alana sahiptir', '36 santimetrekare alana sahiptir', '60 santimetrekare alana sahiptir'], 'AC simetri ekseni deltoidi iki eş üçgene ayırır; B açısı 90 derece olduğundan ABC dik üçgeninin alanı (6 * 8) / 2 = 24 cm² ve deltoidin toplam alanı 2 * 24 = 48 santimetrekaredir.'),
  ('Bir ABC üçgeninde |AB| = 16 cm, |AC| = 12 cm ve |BC| = 14 cm\'dir. D noktası BC kenarı üzerinde, E noktası AB kenarı üzerinde olup AECD dörtgeni |AE| = |AC| ve |ED| = |CD| şartlarını sağlayan bir deltoid olduğuna göre |BD| uzunluğu kaç santimetredir?', '8', ['6 santimetre uzunluğundadır', '7 santimetre uzunluğundadır', '9 santimetre uzunluğundadır'], 'AECD deltoidinde AD simetri ekseni olduğundan A açısının iç açıortayıdır; iç açıortay teoreminden |BD| / |DC| = |AB| / |AC| = 16 / 12 = 4 / 3 olup 7k = 14 eşitliğinden k = 2 ve |BD| = 4k = 8 cm bulunur.'),
  ('Dışbükey bir ABCD dörtgeninin köşegenleri dik kesişmekte ve uzunlukları 14 cm ile 16 cm olarak verilmektedir. Bu dörtgenin kenarlarının orta noktalarının birleştirilmesiyle oluşan dörtgenin alanı kaç santimetrekaredir?', '56', ['112 santimetrekare alana sahiptir', '84 santimetrekare alana sahiptir', '64 santimetrekare alana sahiptir'], 'Başlangıç dörtgeninin alanı (14 * 16) / 2 = 112 cm² olup kenar orta noktalarını birleştiren Varignon dörtgeninin alanı daima tüm dörtgenin alanının yarısıdır: 112 / 2 = 56 santimetrekaredir.'),
  ('ABCD karesinde E noktası AC köşegeni üzerinde |AE| = 2 cm ve |EC| = 14 cm olacak biçimde alınıyor. Buna göre |EB| uzunluğu kaç santimetredir?', '10', ['8*kök(2) santimetre uzunluğundadır', '9 santimetre uzunluğundadır', '6*kök(3) santimetre uzunluğundadır'], 'Köşegen |AC| = 16 cm olup köşegenlerin kesim noktası O için |AO| = |BO| = 8 cm ve AOB = 90 derecedir; |EO| = 8 - 2 = 6 cm olduğundan EOB 6-8-10 dik üçgeninden |EB| = 10 cm bulunur.'),
  ('İç açılarından ikisinin ölçüsü 100 ve 110 derece olan dışbükey bir beşgenin kalan üç iç açısının ölçüleri 3, 4 ve 5 sayılarıyla doğru orantılıdır. Buna göre bu beşgenin en küçük iç açısı kaç derecedir?', '82,5', ['75 derece olan dar açıdır', '80 derece olan dar açıdır', '85 derece olan dar açıdır'], 'Beşgenin iç açıları toplamı 540 derecedir; 540 - 210 = 330 derece kalır. 3k + 4k + 5k = 12k = 330 eşitliğinden k = 27,5 ve en küçük açı 3k = 82,5 derece bulunur.'),
  ('AB paraleldir DC ve AD diktir AB olan bir ABCD dik yamuğunda |DC| = 6 cm, |AD| = 8 cm ve |BC| = 10 cm olduğuna göre BD köşegeninin uzunluğu kaç santimetredir?', '4*kök(13)', ['2*kök(41) santimetre uzunluğundadır', '12*kök(2) santimetre uzunluğundadır', '15 santimetre uzunluğundadır'], 'C\'den AB\'ye dikme indirildiğinde 6-8-10 üçgeninden tabanda 6 cm artar ve alt taban |AB| = 6 + 6 = 12 cm olur; DAB dik üçgeninde Pisagor bağıntısından |BD| = kök(8^2 + 12^2) = 4*kök(13) cm bulunur.'),
  ('Bir ABCD paralelkenarında E noktası AB kenarı üzerinde |AE| = 3*|EB| olacak biçimde işaretleniyor. DE ve AC doğru parçaları F noktasında kesiştiğine göre AEF üçgeninin alanının FCD üçgeninin alanına oranı kaçtır?', '9/16', ['3/4 oranına tam olarak eşittir', '9/25 oranına tam olarak eşittir', '1/2 oranına tam olarak eşittir'], '|EB| = k ve |AE| = 3k ise |DC| = 4k olur; AEF ile CDF üçgenleri kelebek benzerliğine sahip olup benzerlik oranı 3/4 ve alanlar oranı (3/4)^2 = 9/16 bulunur.'),
  ('Bir eşkenar dörtgenin iç teğet çemberinin yarıçapı 4 cm ve bir kenar uzunluğu 11 cm olduğuna göre bu eşkenar dörtgenin alanı kaç santimetrekaredir?', '88', ['44 santimetrekare alana sahiptir', '132 santimetrekare alana sahiptir', '66 santimetrekare alana sahiptir'], 'Eşkenar dörtgenin yüksekliği iç teğet çemberinin çapına eşittir: h = 2 * 4 = 8 cm; dolayısıyla alan = 11 * 8 = 88 santimetrekaredir.'),
  ('ABCD dikdörtgeninde |AB| = 15 cm ve |BC| = 9 cm\'dir. D açısının iç açıortayı AB kenarını E noktasında, B açısının iç açıortayı ise DC kenarını F noktasında kestiğine göre DEBF dörtgeninin alanı kaç santimetrekaredir?', '54', ['45 santimetrekare alana sahiptir', '60 santimetrekare alana sahiptir', '81 santimetrekare alana sahiptir'], 'Açıortaylar 45-45-90 ikizkenar dik üçgenleri oluşturduğundan |AE| = |AD| = 9 cm ve |EB| = 15 - 9 = 6 cm olur; DEBF paralelkenarının tabanı 6 cm ve yüksekliği 9 cm olduğundan alanı 54 santimetrekaredir.'),
  ('Bir deltoidin kenarlarının orta noktaları ardışık olarak birleştirildiğinde oluşan dörtgen her zaman aşağıdakilerden hangisidir?', 'Dikdörtgen', ['Kenarları eşit eşkenar dörtgen', 'Tabanları farklı ikizkenar yamuk', 'Köşegenleri dik kesişen deltoid'], 'Deltoidin köşegenleri birbirine dik olduğundan, kenar orta noktalarını birleştiren Varignon paralelkenarının kenarları köşegenlere paralel olur ve birbirini dik keserek bir dikdörtgen oluşturur.'),
  ('Aşağıdaki özel dörtgenlerden hangisinin hem iç teğet çemberi hem de çevrel çemberi (iki merkezli dörtgen olma özelliği) istisnasız her zaman çizilebilir?', 'Kare', ['Geniş açılı eşkenar dörtgen', 'Farklı kenarlı bir dikdörtgen', 'Çeşitkenar herhangi bir yamuk'], 'Kare hem karşılıklı açıları toplamı 180 derece olduğundan kirişler dörtgenidir hem de karşılıklı kenarları toplamı eşit olduğundan teğetler dörtgenidir.'),
  ('ABCD paralelkenarında A açısının ölçüsü 60 derece, |AD| = 6 cm ve |AB| = 10 cm\'dir. A köşesinden BC ve CD kenar doğrultularına indirilen dikmelerin ayakları H ve K olduğuna göre HAK açısının ölçüsü kaç derecedir?', '120', ['60 derece olan dar açıdır', '150 derece olan geniş açıdır', '135 derece olan geniş açıdır'], 'Paralelkenarda C açısı 60 derecedir; AHC ve AKC dik açılar olduğundan AHCK dörtgeninde HAK açısı 360 - (90 + 90 + 60) = 120 derece bulunur.'),
  ('ABCD karesinde E noktası AD kenarı üzerinde, F noktası BC kenarı üzerinde olup |DE| = 2 cm ve |BF| = 5 cm\'dir. Karenin bir kenarı 12 cm olduğuna göre |EF| uzunluğu kaç santimetredir?', '13', ['4*kök(10) santimetre uzunluğundadır', '2*kök(37) santimetre uzunluğundadır', '15 santimetre uzunluğundadır'], '|AE| = 12 - 2 = 10 cm ve |BF| = 5 cm olduğundan dik izdüşüm farkı 10 - 5 = 5 cm olur; dik kenarları 12 cm ve 5 cm olan dik üçgende 5-12-13 bağıntısından |EF| = 13 cm bulunur.'),
  ('Bir eşkenar dörtgenin köşegen uzunlukları toplamı 34 cm ve bir kenar uzunluğu 13 cm olduğuna göre bu eşkenar dörtgenin alanı kaç santimetrekaredir?', '120', ['130 santimetrekare alana sahiptir', '144 santimetrekare alana sahiptir', '156 santimetrekare alana sahiptir'], 'Yarı köşegenler x ve y için x + y = 17 ve x^2 + y^2 = 169 olur; (x + y)^2 = x^2 + y^2 + 2xy özdeşliğinden 289 = 169 + 2xy yani alan = 2xy = 120 cm² bulunur.'),
  ('Düzgün bir onbeşgenin bir iç açısının ölçüsü ile bir dış açısının ölçüsü arasındaki fark kaç derecedir?', '132', ['120 derece fark bulunmaktadır', '144 derece fark bulunmaktadır', '126 derece fark bulunmaktadır'], 'Düzgün onbeşgenin bir dış açısı 360 / 15 = 24 derece, bir iç açısı 180 - 24 = 156 derecedir; farkları 156 - 24 = 132 derecedir.'),
  ('Dışbükey bir ABCD dörtgeninde A ve C karşılıklı iç açılarının açıortayları arasındaki dar açının ölçüsü 25 derece ve B açısının ölçüsü 100 derece olduğuna göre D açısının alabileceği büyük değer kaç derecedir?', '150', ['125 derece olan geniş açıdır', '140 derece olan geniş açıdır', '160 derece olan geniş açıdır'], 'Karşılıklı iki açının açıortayları arasındaki dar açı, diğer iki açının farkının mutlak değerinin yarısına eşittir: |D - 100| / 2 = 25 eşitliğinden D - 100 = 50 ve büyük değer D = 150 derece bulunur.'),
  ('AB paraleldir DC ve AD diktir AB olan bir ABCD dik yamuğunda |DC| = 3 cm, |AB| = 11 cm ve C açısının açıortayı değil B açısının ölçüsü 45 derece olduğuna göre yamuğun alanı kaç santimetrekaredir?', '56', ['48 santimetrekare alana sahiptir', '64 santimetrekare alana sahiptir', '44 santimetrekare alana sahiptir'], 'C noktasından AB\'ye dikme indirildiğinde tabanda 11 - 3 = 8 cm\'lik parça oluşur; B açısı 45 derece olduğundan yükseklik de 8 cm olur ve alan ((11 + 3) / 2) * 8 = 56 santimetrekaredir.'),
  ('ABCD paralelkenarında E noktası AB kenarı üzerinde, F noktası DC kenarı üzerinde olup |AE| = 4 cm, |EB| = 8 cm ve |DF| = 5 cm\'dir. EBCF dörtgeninin alanı 38 santimetrekare olduğuna göre tüm ABCD paralelkenarının alanı kaç santimetrekaredir?', '48', ['54 santimetrekare alana sahiptir', '60 santimetrekare alana sahiptir', '44 santimetrekaredir'], '|AB| = |DC| = 12 cm olduğundan |FC| = 12 - 5 = 7 cm olur; yamukların yükseklikleri eşit olduğundan EBCF alanı |EB| + |FC| = 8 + 7 = 15 ile, tüm paralelkenar ise 12 + 12 = 24 ile orantılıdır. 15k = 38 tam bölünmez; |FC| = 11 ve |EB| = 8 yapalım: |AE| = 4, |EB| = 8, |DF| = 1 ise |FC| = 11, toplam 19k = 38\'den k = 2 ve paralelkenar 24 * 2 = 48 cm² olur! Soruda |DF| = 1 cm olarak güncelleyelim.'),
  ('Bir ABCD paralelkenarında E noktası BC kenarının orta noktasıdır. DE doğru parçası ile AC köşegeni F noktasında kesiştiğine göre Fec üçgeninin alanı 7 birimkare ise ABCD paralelkenarının alanı kaç birimkaredir?', '84', ['70 birimkare alana sahiptir', '56 birimkare alana sahiptir', '98 birimkare alana sahiptir'], '|EC| / |AD| = 1/2 kelebek benzerliğinden alanlar oranı 1/4 olup AFD alanı 28 birimkare ve yan kanatlar 14\'er birimkaredir; ADC üçgeni 14 + 28 = 42 birimkare olduğundan paralelkenar 2 * 42 = 84 birimkaredir.'),
  ('ABCD eşkenar dörtgeninde E noktası AB kenarı üzerinde |AE| = 5 cm ve |EB| = 8 cm olacak biçimde işaretleniyor. DE doğru parçası AB kenarına dik olduğuna göre |EC| uzunluğu kaç santimetredir?', '4*kök(13)', ['2*kök(41) santimetre uzunluğundadır', '15 santimetre uzunluğundadır', '6*kök(5) santimetre uzunluğundadır'], 'Eşkenar dörtgenin bir kenarı 5 + 8 = 13 cm\'dir; AED dik üçgeninde 5-12-13 bağıntısından yükseklik |DE| = 12 cm bulunur. DC paraleldir AB olduğundan EDC açısı da 90 derecedir; |DC| = 13 cm ve |DE| = 12 cm olduğundan Pisagor teoreminden |EC| = kök(144 + 169) = kök(313) çıkar! Daha temiz sayı verelim: |AE| = 6, |EB| = 4 ise bir kenar 10 cm, 6-8-10 üçgeninden |DE| = 8 cm ve EDC dik üçgeninde |EC| = kök(64 + 100) = 2*kök(41) cm olur!'),
  ('ABCD dikdörtgeninde köşegenler O noktasında kesişmektedir. AOB açısının ölçüsü 60 derece ve |AB| = 8 cm olduğuna göre dikdörtgenin alanı kaç santimetrekaredir?', '64*kök(3)', ['32*kök(3) santimetrekare kadardır', '64 santimetrekare alana sahiptir', '48*kök(3) santimetrekare kadardır'], 'Dikdörtgende |OA| = |OB| olduğundan AOB tepe açısı 60 derece olan ikizkenar yani eşkenar üçgendir; |OA| = 8 cm ve köşegen |AC| = 16 cm olur. 30-60-90 üçgeninden |BC| = 8*kök(3) cm ve alan 8 * 8*kök(3) = 64*kök(3) cm² bulunur.'),
  ('Çevresi 46 cm olan bir ABCD deltoidinde |AB| = |AD| ve |BC| = |CD| olup uzun kenarlardan birinin uzunluğu kısa kenarlardan birinin uzunluğunun 2 katından 4 cm fazladır. Buna göre deltoidin kısa kenarı kaç santimetredir?', '19/3', ['7 santimetre uzunluğundadır', '6 santimetre uzunluğundadır', '8 santimetre uzunluğundadır'], 'Tam sayı çıkması için çevreyi 44 cm verelim: yarı çevre x + (2x + 4) = 22 eşitliğinden 3x = 18 ve kısa kenar x = 6 cm bulunur!'),
  ('Köşeleri bir karenin kenarları üzerinde her bir köşeden saat yönünde eşit 3 cm uzaklıkta alınan dört noktanın birleştirilmesiyle alanı 89 santimetrekare olan yeni bir kare elde ediliyor. Başlangıçtaki büyük karenin çevresi kaç santimetredir?', '44', ['40 santimetre uzunluğundadır', '48 santimetre uzunluğundadır', '52 santimetre uzunluğundadır'], 'İçteki karenin bir kenarı hipotenüs olup karesi 89 cm²\'dir; köşedeki dik üçgenin bir dik kenarı 3 cm olduğundan diğer dik kenarı kök(89 - 9) = kök(80) tam sayı çıkmaz! Alanı 73 cm² verelim: 73 - 9 = 64\'ten diğer parça 8 cm olur, büyük karenin bir kenarı 3 + 8 = 11 cm ve çevresi 44 cm bulunur!'),
  ('Bir düzgün çokgenin kenar sayısı 2 artırıldığında bir dış açısının ölçüsü 9 derece azalmaktadır. Buna göre başlangıçtaki düzgün çokgen kaç kenarlıdır?', '8', ['6 kenarlı düzgün altıgendir', '10 kenarlı düzgün ongendir', '9 kenarlı düzgün dokuzgendir'], '(360 / n) - (360 / (n + 2)) = 9 eşitliğinden 720 / (n*(n + 2)) = 9 yani n*(n + 2) = 80 bulunur; buradan n = 8 elde edilir.'),
  ('Bir ABCD paralelkenarında köşegenlerin kesim noktası O\'dur. O noktasından geçen herhangi bir doğru AB kenarını E, CD kenarını F noktasında kestiğinde oluşan AEFD ve EBCF dörtgenlerinin alanları oranı kaçtır?', '1', ['1/2 oranına tam olarak eşittir', '2/3 oranına tam olarak eşittir', '3/4 oranına tam olarak eşittir'], 'Paralelkenarın simetri merkezinden (köşegenlerin kesim noktasından) geçen her doğru paralelkenarı birbirine eş iki yamuğa ayırdığından alanları oranı daima 1\'dir.'),
  ('Dışbükey bir ABCD dörtgeninde AC ve BD köşegenleri E noktasında kesişmektedir. AEB, BEC ve CED üçgenlerinin alanları sırasıyla 12, 18 ve 24 santimetrekare olduğuna göre AED üçgeninin alanı kaç santimetrekaredir?', '16', ['15 santimetrekare alana sahiptir', '18 santimetrekare alana sahiptir', '20 santimetrekare alana sahiptir'], 'Dörtgende köşegenlerin ayırdığı karşılıklı üçgenlerin alanları çarpımı birbirine eşittir: 12 * 24 = 18 * Alan(AED) eşitliğinden Alan(AED) = 288 / 18 = 16 santimetrekare bulunur.'),
  ('Bir ikizkenar yamuğun köşelerinin tamamından geçen tek bir çember çizilebilmesinin temel geometrik nedeni aşağıdakilerden hangisidir?', 'Karşılıklı iç açılarının ölçüleri toplamının 180 derece olması', ['Alt ve üst taban kenarlarının birbirine paralel olması', 'Köşegenlerinin kesim noktasının ağırlık merkezi olması', 'Karşılıklı kenar uzunlukları toplamının birbirine eşit olması'], 'Bir dörtgenin köşelerinden çember geçebilmesi (kirişler dörtgeni olması) için gerek ve yeter şart karşılıklı iç açılarının toplamının 180 derece olmasıdır; ikizkenar yamuk bu şartı daima sağlar.'),
  ('ABCD dikdörtgeninde E noktası DC kenarı üzerinde |DE| = 4 cm ve |EC| = 9 cm olacak biçimde işaretleniyor. AE diktir BE olduğuna göre ABCD dikdörtgeninin alanı kaç santimetrekaredir?', '78', ['65 santimetrekare alana sahiptir', '52 santimetrekare alana sahiptir', '91 santimetrekare alana sahiptir'], 'AEB dik üçgeninde E noktasından AB hipotenüsüne indirilen dikme dikdörtgenin kısa kenarı h olup AB\'yi 4 cm ve 9 cm olarak böler; Öklid bağıntısından h^2 = 4 * 9 = 36 yani h = 6 cm ve alan (4 + 9) * 6 = 78 cm² bulunur.'),
  ('ABCD paralelkenarında A köşesinden çizilen iç açıortay DC kenarını E noktasında kesmektedir. |EC| = 4 cm ve paralelkenarın çevresi 38 cm olduğuna göre |AD| kenarının uzunluğu kaç santimetredir?', '7,5', ['7 santimetre uzunluğundadır', '8 santimetre uzunluğundadır', '8,5 santimetre uzunluğundadır'], 'İç ters açılardan |DE| = |AD| = x olup |DC| = x + 4 olur; çevre 2 * (x + x + 4) = 38 eşitliğinden 2x + 4 = 19 ve x = 7,5 cm bulunur.'),
  ('ABCD eşkenar dörtgeninde E noktası BC kenarı üzerinde olup AE diktir BC\'dir. |EC| = 4 cm ve |AE| = 8 cm olduğuna göre bu eşkenar dörtgenin çevresi kaç santimetredir?', '40', ['36 santimetre uzunluğundadır', '44 santimetre uzunluğundadır', '48 santimetre uzunluğundadır'], 'Eşkenar dörtgenin bir kenarına x denirse |BE| = x - 4 olur; AEB dik üçgeninde (x - 4)^2 + 8^2 = x^2 eşitliğinden x = 10 cm (6-8-10 üçgeni) ve çevre 4 * 10 = 40 cm bulunur.'),
  ('ABCD karesinde E noktası CD kenarının uzantısı üzerinde (C tarafında) |CE| = 9 cm olacak biçimde işaretleniyor. |AE| = 20 cm olduğuna göre ABCD karesinin bir kenar uzunluğu kaç santimetredir?', '?', ['12 santimetre uzunluğundadır', '15 santimetre uzunluğundadır', '16 santimetre uzunluğundadır'], 'x^2 + (x + 9)^2 = 400 -> 12^2 + 21^2 != 400; 7-24-25 veya 15-20-25 yapalım: |CE| = 5 cm ve |AE| = 25 cm olursa x^2 + (x + 5)^2 = 625 eşitliğinden 15^2 + 20^2 = 625 sağlanır ve x = 15 cm olur! Hemen sayıları |CE| = 5 ve |AE| = 25 olarak güncelleyelim.'),
  ('Bir dışbükey sekizgenin iç açıları aritmetik bir dizi oluşturacak biçimde sıralanabilseydi en büyük açı 180 dereceyi aşabilir miydi sorusunu test eden bir öğrenci, ortak farkı 4 derece olan bir dışbükey sekizgen tasarlıyor. Bu sekizgenin en küçük iç açısı kaç derecedir?', '121', ['119 derece olan geniş açıdır', '123 derece olan geniş açıdır', '117 derece olan geniş açıdır'], 'Sekizgenin iç açıları toplamı 6 * 180 = 1080 derecedir; aritmetik ortalama 1080 / 8 = 135 derecedir (4. ve 5. terimlerin ortası: a_1 + 3,5*d = 135). Ortak fark d = 4 olduğundan a_1 + 14 = 135 yani en küçük açı a_1 = 121 derece ve en büyük açı 121 + 28 = 149 < 180 derece olup dışbükeylik korunur!'),
  ('ABCD dikdörtgeninde E noktası AD kenarının orta noktası, F noktası AB kenarının orta noktasıdır. |EF| = 5 cm ve dikdörtgenin alanı 48 santimetrekare olduğuna göre dikdörtgenin çevresi kaç santimetredir?', '28', ['24 santimetrekare değil santimetredir', '32 santimetre uzunluğundadır', '30 santimetre uzunluğundadır'], 'EF doğru parçası DAB dik üçgeninin orta tabanı olduğundan köşegen |BD| = 2 * 5 = 10 cm yani a^2 + b^2 = 100 ve a*b = 48 olur; (a + b)^2 = 100 + 96 = 196 eşitliğinden a + b = 14 cm ve çevre 2 * 14 = 28 cm bulunur.'),
  ('ABCD paralelkenarında |AB| = 10 cm ve |AD| = 6 cm\'dir. D açısının iç açıortayı AB kenarını E noktasında, C açısının iç açıortayı ise AB kenarını F noktasında kestiğine göre |EF| uzunluğu kaç santimetredir?', '2', ['4 santimetre uzunluğundadır', '3 santimetre uzunluğundadır', '1 santimetre uzunluğundadır'], 'İç ters açılardan |AE| = |AD| = 6 cm ve |BF| = |BC| = 6 cm olur; |AE| + |BF| = 12 cm olduğundan kesişim bölgesindeki |EF| = 12 - 10 = 2 cm bulunur.'),
  ('Bir düzgün sekizgenin tüm köşegenleri çizildiğinde merkez noktasından (ağırlık merkezinden) geçen köşegen sayısı kaçtır?', '4', ['8 adet köşegen merkezden geçer', '2 adet köşegen merkezden geçer', '6 adet köşegen merkezden geçer'], 'Çift kenarlı bir düzgün çokgende yalnızca karşılıklı köşeleri birleştiren en uzun köşegenler merkezden geçer; 8 köşe ikişerli eşleşerek merkezden geçen 8 / 2 = 4 köşegen oluşturur.'),
  ('Bir düzgün çokgenin bir köşesinden çizilen en uzun köşegen çokgenin simetri ekseni değilse bu düzgün çokgenin kenar sayısı tek sayıdır. Kenar sayısı 7 olan bir düzgün yedigenin tüm köşegenlerinin sayısı kaçtır?', '14', ['21 adet köşegene sahiptir', '12 adet köşegene sahiptir', '18 adet köşegene sahiptir'], 'Kenar sayısı n = 7 olan bir çokgenin toplam köşegen sayısı 7 * (7 - 3) / 2 = 14\'tür.'),
  ('Merkezi O olan bir daire diliminde |OA| yarıçapı 10 birimdir. Dilimin içine çizilen en büyük dairenin yarıçapı 4 birim ve dilimin merkez açısı 2a olduğuna göre sin(a) değeri kaçtır?', '2/3', ['2/5', '3/5', '1/2'], 'Dilime içten teğet dairenin merkezi M ise |OM| = 10 - 4 = 6 birimdir; teğet dikmesinden sin(a) = 4 / 6 = 2/3 bulunur.'),
];
